var FLO_PHASE_EMOJI = { period:'🩸', follicular:'🌱', fertile:'🌸', luteal:'🍂' };
function floRingGradient(config){
  var cl = config.cycleLength, pl = config.periodLength;
  var ovulationOffset = Math.max(1, cl - 14);
  var fertileStartOffset = Math.max(1, ovulationOffset - 5);
  var fertileEndOffset = ovulationOffset + 1;
  var segs = [
    { end: pl, color: FLO_PHASES.period.color },
    { end: Math.max(pl, fertileStartOffset-1), color: FLO_PHASES.follicular.color },
    { end: fertileEndOffset, color: FLO_PHASES.fertile.color },
    { end: cl, color: FLO_PHASES.luteal.color }
  ];
  var stops = [], prev = 0;
  segs.forEach(function(s){
    var pct = Math.max(prev, Math.min(100, s.end/cl*100));
    if (pct > prev){ stops.push(s.color+' '+prev.toFixed(2)+'% '+pct.toFixed(2)+'%'); prev = pct; }
  });
  return 'conic-gradient(from 0deg, '+stops.join(', ')+')';
}
