  var exts = opts.extensions.map(function(e){ return '.' + e; });
  var accept = exts.join(',') + (opts.extensions.some(function(e){ return /^(png|jpe?g|webp|gif)$/.test(e); }) ? ',image/*' : '') + (opts.extensions.some(function(e){ return /^(mp4|webm|mov)$/.test(e); }) ? ',video/*' : '');
