var LB_NAME_PREFIX = 'Телефон отношений';
async function rpGetStrict(key){
  return await withTimeout(Promise.resolve().then(function(){ return PM.store.get(key, 'chat'); }).then(function(v){ return { ok:true, v: v === undefined ? null : v }; }, function(){ return { ok:false }; }), 8000, { ok:false });
}
async function ensureLorebook(opts){
  opts = opts || {};
  var rid = await rpGetStrict('rp_lb_id');
  if (!rid.ok) return null;
  var lbId = rid.v;
  if (lbId){
    for (var tr = 0; tr < 2; tr++){
      var got = await withTimeout(Promise.resolve().then(function(){ return PM.lore.get(lbId); }).then(function(v){ return { v: v }; }, function(){ return { err:true }; }), 8000, { err:true });
      if (got.v) return got.v;
      if (got.err && opts.noCreate) return null;
      await new Promise(function(r){ setTimeout(r, 1200); });
    }
    if (opts.noCreate) return null;
  } else if (opts.noCreate) return null;
  var names = await getNames();
  var lbName = LB_NAME_PREFIX + ': ' + names.charName + ' \u2194 ' + names.userName;
  var found = [];
  try{ found = (await PM.lore.find(lbName)) || []; }catch(e){}
  if (found && found.length){
    var choice = await showChoiceModal({
      title: 'Найден лорбук этого персонажа',
      message: 'У «'+names.charName+'» уже есть лорбук «'+lbName+'» из другого чата. Добавлять телефонные записи в него, или вести отдельный лорбук для этого чата?',
      buttons: [
        { label: 'Добавлять в существующий', value: 'use' },
        { label: 'Создать отдельный для этого чата', value: 'new', ghost: true }
      ]
    });
    if (choice === 'use'){
      await rpSet('rp_lb_id', found[0].id);
      await attachLorebook(found[0].id);
      return found[0];
    }
    lbName = lbName + ' (' + todayISODate() + ')';
  }
  try{
    var newId = await PM.lore.create(lbName);
    await rpSet('rp_lb_id', newId);
    await attachLorebook(newId);
    return await PM.lore.get(newId);
  }catch(e){ console.error('RP lorebook create failed', e); toast('Не удалось создать лорбук: ' + (e && e.message ? e.message : e)); return null; }
}
async function attachLorebook(id){
  try{ await PM.lore.bind(id); }
  catch(e){ console.error('RP attach lorebook failed', e); toast('Лорбук создан, но не подключился к чату: ' + (e && e.message ? e.message : e)); }
}
async function getLoreLang(){ return await rpGet('rp_lore_lang', 'ru'); }
async function localizeForLore(text){
  if (!text) return text;
  var lang = await getLoreLang();
  if (lang !== 'en') return text;
  try{
    var translated = await callModel('Переведи следующий текст на английский язык, сохраняя смысл, структуру и переносы строк, ничего не добавляя от себя:\n\n'+text+'\n\nОтветь только переводом, без пояснений.');
    var t = String(translated||'').trim();
    return t || text;
  }catch(e){ console.error('RP localizeForLore failed', e); return text; }
}
async function upsertLorebookEntry(identifier, name, content, opts){
  var lb = await ensureLorebook(opts);
  if (!lb) return;
  content = await localizeForLore(content);
  var entries = lb.entries || [];
  var entry = entries.find(function(e){ return e.identifier===identifier; });
  if (entry) entry.content = content;
  else entries.push({ identifier:identifier, name:name, content:content, enabled:true, strategy:'constant' });
  lb.entries = entries;
  try{ await PM.lore.save(lb); }catch(e){ console.error('RP lorebook update failed', e); toast('Не удалось обновить лорбук: ' + (e && e.message ? e.message : e)); }
}

