var SCREENS = {};

function sanitizeShortReply(text, maxLen){
  var s = String(text||'').trim();
  if (!s) return '';
  s = s.replace(/<[^>]+>/g, ' ');
  s = s.replace(/\[[A-Za-z0-9_]{1,16}\][\s\S]*?\[\/[A-Za-z0-9_]{1,16}\]/g, ' ');
  s = s.replace(/```[\s\S]*?```/g, ' ');
  s = s.replace(/[ \t]+/g, ' ').trim();
  if (!s) return '';
  var paraCheckText = s.replace(/\[NEXT\]/gi, ' ');
  var paraCount = (paraCheckText.match(/\n{2,}/g) || []).length;
  if (paraCount > 1) return '';
  if (s.length > (maxLen || 350)) return '';
  return s;
}
async function callModelForMessage(prompt, maxLen){
  try{
    var raw = await callModel(prompt);
    var text = String(raw||'').trim();
    text = text.replace(/^```[a-zA-Z]*\n?/, '').replace(/```$/, '').trim();
    text = text.replace(/^"([\s\S]*)"$/, '$1').trim();
    text = sanitizeShortReply(text, maxLen);
    return text;
  }catch(e){ console.error('RP message generation failed', e); return ''; }
}

function buildChatImagePrompt(desc, senderName, kind){
  var base = desc || ('a candid photo of '+(senderName||'a person')+' in an everyday moment');
  var common = ', real-life snapshot, amateur phone camera photo, ' + (/Lighting:/.test(base) ? '' : 'natural lighting, ') + 'candid, photorealistic, no text, no UI, no app interface, no screenshot elements, no frame, no overlay, no watermark, no borders';
  if (kind === 'circle') return base + ', close-up selfie-angle shot, front camera angle'+common;
  return base + common;
}
var RP_FAM = [
  ['mom', /^(мама|мамуля|мамулька|мамулечка|мамочка|мамка|мамуся|мамуська|мамусик|мамуш\S*|мамскин|мамс|мамси|мамчик|мать|матушка|маман|мамаша|mom|mommy|mum|mummy|mama)$/],
  ['dad', /^(папа|папуля|папочка|папка|папс|папаша|батя|батяня|отец|dad|papa)$/],
  ['gma', /^(бабушка|бабуля|бабуся|бабуська|баба|ба)$/],
  ['gpa', /^(дедушка|дедуля|деда|дед)$/],
  ['bro', /^(брат|братик|братишка|брательник|братец)$/],
  ['sis', /^(сестра|сестрёнка|сестренка|сестричка|систер|сеструха|сестрица|sis|sister)$/]
];
function rpFamKey(name){
  var toks = String(name || '').toLowerCase().replace(/[^a-zа-яё0-9]+/gi, ' ').trim().split(' ').filter(function(t){ return t && !/^(мой|моя|мое|моё|my|любимая|любимый|родная|родной)$/.test(t); });
  if (toks.length !== 1) return '';
  for (var i = 0; i < RP_FAM.length; i++){ if (RP_FAM[i][1].test(toks[0])) return RP_FAM[i][0]; }
  return '';
}
var RP_ROLE_RE = /^(юрист|адвокат|нотариус|менеджер|монтаж|монтажер|модер|модератор|админ|администратор|оператор|редактор|продюсер|агент|тренер|врач|доктор|медсестра|психолог|терапевт|стоматолог|препод|преподаватель|учитель|училка|репетитор|куратор|декан|директор|босс|шеф|начальник|начальница|коллега|сосед|соседка|друг|подруга|дружище|охрана|охранник|водитель|курьер|бухгалтер|следователь|опер|участковый|риелтор|риэлтор|стилист|визажист|фотограф|няня|секретарь|секретарша|помощник|помощница|ассистент|личный|личная|рабочий|рабочая|новый|новая|номер|тел|контакт)$/;
var RP_PATRO_MAP = { 'саныч':'александр', 'палыч':'павл', 'михалыч':'михайл' };
function rpNameToks(x){ return String(x || '').toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9]+/gi, ' ').trim().split(' ').filter(Boolean); }
function rpNameCore(x){ var t = rpNameToks(x), c = t.filter(function(w){ return !RP_ROLE_RE.test(w); }); return c.length ? c : t; }
function rpPatro(tok){
  if (RP_PATRO_MAP[tok]) return { root: RP_PATRO_MAP[tok], short: true };
  var m = /^(.{3,}?)(ьевич|ович|евич|овна|евна|ична|ыч|ич)$/.exec(tok);
  return m ? { root: m[1].replace(/[ьи]+$/, ''), short: m[2] === 'ыч' || m[2] === 'ич' } : null;
}
function rpNameSame(a, b, grp){
  var ta = rpNameToks(a), tb = rpNameToks(b);
  if (!ta.length || !tb.length) return false;
  if (ta.join(' ') === tb.join(' ')) return true;
  if (/,/.test(a) || /,/.test(b)) return false;
  if (grp){ var sh = ta.length <= tb.length ? ta : tb, lg = sh === ta ? tb : ta; return sh.length >= 2 && sh.every(function(w){ return lg.indexOf(w) >= 0; }); }
  var ca = rpNameCore(a), cb = rpNameCore(b);
  if (ca.join(' ') === cb.join(' ')) return true;
  var pa = ca.map(rpPatro), pb = cb.map(rpPatro);
  var hit = function(P, Q){ return P.some(function(x){ return x && (x.short || P.length === 1) && Q.some(function(y){ return y && y.root === x.root; }); }); };
  if ((ca.length <= 2 && hit(pa, pb)) || (cb.length <= 2 && hit(pb, pa))) return true;
  return scanSameName(ca.join(' '), cb.join(' '));
}
function rpSameContact(c, name){
  if (!c || !c.name) return false;
  var b = String(name || '').trim(); if (!b) return false;
  var fk = rpFamKey(b);
  return [c.name].concat(c.aliases || []).some(function(x){
    x = String(x || '').trim(); if (!x) return false;
    if (x.toLowerCase() === b.toLowerCase()) return true;
    if (fk && rpFamKey(x) === fk) return true;
    return rpNameSame(x, b, !!c.group);
  });
}

function parseTwitchChatBlocks(text){
  var blocks = [];
  var re = /\[TCH\]([\s\S]*?)\[\/TCH\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var streamer = '', title = '', viewers = '', chatLines = [];
    lines.forEach(function(line){
      var sm = /^streamer\s*:\s*(.*)$/i.exec(line);
      if (sm){ streamer = sm[1].trim(); return; }
      var tm = /^title\s*:\s*(.*)$/i.exec(line);
      if (tm){ title = tm[1].trim(); return; }
      var vm = /^viewers\s*:\s*(.*)$/i.exec(line);
      if (vm){ viewers = vm[1].trim(); return; }
      var cm = /^([^:]{1,24})\s*:\s*([\s\S]+?)\s*(?:\|\s*(#[0-9a-fA-F]{3,6})\s*)?$/.exec(line);
      if (cm) chatLines.push({ nick: cm[1].trim(), text: cm[2].trim(), colour: (cm[3]||'').trim() });
    });
    if (chatLines.length) blocks.push({ streamer:streamer, title:title, viewers:viewers, lines:chatLines });
  }
  return blocks;
}
function parseTwitchDonationBlocks(text){
  var blocks = [];
  var re = /\[TWITCH_DONATION_EPIC\]([\s\S]*?)\[\/TWITCH_DONATION_EPIC\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var d = { donator:'', amount:'', message:'', tier:'' };
    lines.forEach(function(line){
      var m;
      if ((m = /^donator\s*:\s*(.*)$/i.exec(line))) d.donator = m[1].trim();
      else if ((m = /^amount\s*:\s*(.*)$/i.exec(line))) d.amount = m[1].trim();
      else if ((m = /^message\s*:\s*(.*)$/i.exec(line))) d.message = m[1].trim();
      else if ((m = /^tier\s*:\s*(.*)$/i.exec(line))) d.tier = m[1].trim();
    });
    if (d.donator) blocks.push(d);
  }
  return blocks;
}
async function maybeImportTwitchTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_twitch_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_twitch_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_twitch_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_twitch_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var text = rpTagText(String(m.content));
      var chatBlocks = parseTwitchChatBlocks(text);
      var donationBlocks = parseTwitchDonationBlocks(text);
      if (!chatBlocks.length && !donationBlocks.length) continue;

      var session = await rpGet('rp_stream_session', null);
      if (!session){
        var settings = await rpGet('rp_twitch_settings', { streamerMode:'char' });
        session = { startedAt: Date.now(), streamerMode: settings.streamerMode, auto:true };
        await rpSet('rp_stream_session', session);
        await rpSet('rp_stream_feed', []);
        await rpSet('rp_stream_chat', []);
      }

      for (var ci=0; ci<chatBlocks.length; ci++){
        var block = chatBlocks[ci];
        if (block.title){
          var s2 = await rpGet('rp_stream_session', {});
          s2.title = block.title;
          await rpSet('rp_stream_session', s2);
        }
        var chat = await rpGet('rp_stream_chat', []);
        block.lines.forEach(function(l){
          chat.push({ id: uid(), author: l.nick, text: l.text, colour: l.colour||'', ts: Date.now(), type:'chat' });
        });
        await rpSet('rp_stream_chat', chat.slice(-300));
        touched = true;
      }
      for (var di=0; di<donationBlocks.length; di++){
        var d = donationBlocks[di];
        var chat2 = await rpGet('rp_stream_chat', []);
        chat2.push({ id: uid(), author: d.donator, text: d.message, amount: d.amount, tier: d.tier, ts: Date.now(), type:'donation' });
        await rpSet('rp_stream_chat', chat2.slice(-300));
        var amountNum = parseInt(String(d.amount).replace(/[^\d]/g,''),10) || 0;
        if (amountNum){
          var bal = await rpGet('rp_twitch_balance', 0);
          await rpSet('rp_twitch_balance', bal + amountNum);
        }
        touched = true;
      }
    }

    if (touched){
      if (panelOpen && currentScreen === 'twitch'){
        var scope = $('.rp_twitch_scope');
        if (scope) await renderTwitchBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Twitch', 'Новое событие на стриме');
      }
    }
  }catch(e){ console.error('RP twitch tag import failed', e); }
}
async function maybeAutonomousReminder(){
  try{
    var conf = await rpGet('rp_autonomy_love', null);
    if (!conf || !conf.enabled) return;
    var intervalMs = Math.max(3, Number(conf.intervalMin)||20) * 60000;
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watch = await rpGet('rp_autonomy_watch_love', null);
    if (!watch || watch.count !== count){
      await rpSet('rp_autonomy_watch_love', { count: count, at: Date.now() });
      return;
    }
    if (Date.now() - watch.at < intervalMs) return;
    var lastAuto = await rpGet('rp_autonomy_last_love', 0);
    if (Date.now() - lastAuto < intervalMs) return;
    if (Math.random() > 0.4) return;
    await rpSet('rp_autonomy_last_love', Date.now());

    var reminderText = await generateReminder();
    if (!reminderText) return;
    var reminders = await rpGet('rp_reminders', []);
    reminders.push({ id: uid(), text: reminderText, ts: Date.now(), hidden:false });
    await rpSet('rp_reminders', reminders.slice(-200));
    if (panelOpen && currentScreen === 'love'){
      var rw = $('#rp_reminders_jar');
      if (rw) await renderRemindersJar(rw);
    } else {
      unreadCount++; updateBadge();
      pushHomeNotification('Love', reminderText.slice(0,120));
    }
  }catch(e){ console.error('RP autonomy (love) failed', e); }
}
async function maybeAutonomousTweet(){
  try{
    var conf = await rpGet('rp_autonomy_twitter', null);
    if (!conf || !conf.enabled) return;
    var intervalMs = Math.max(3, Number(conf.intervalMin)||20) * 60000;
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watch = await rpGet('rp_autonomy_watch_twitter', null);
    if (!watch || watch.count !== count){
      await rpSet('rp_autonomy_watch_twitter', { count: count, at: Date.now() });
      return;
    }
    if (Date.now() - watch.at < intervalMs) return;
    var lastAuto = await rpGet('rp_autonomy_last_twitter', 0);
    if (Date.now() - lastAuto < intervalMs) return;
    if (Math.random() > 0.4) return;
    await rpSet('rp_autonomy_last_twitter', Date.now());

    var text = await generateAutonomousTweet();
    if (!text) return;
    var names = await getNames();
    var tweets = await rpGet('rp_tweets', []);
    tweets.unshift({ id: uid(), author: names.charName, handle: names.charName.toLowerCase().replace(/\s+/g,''), text: text, ts: Date.now(), kind:'char',
      likes: Math.floor(Math.random()*40), liked:false, retweets: Math.floor(Math.random()*10), views: Math.floor(Math.random()*2000)+50, comments:null, commentCount: 5+Math.floor(Math.random()*16) });
    await rpSet('rp_tweets', tweets.slice(0,80));
    if (panelOpen && currentScreen === 'twitter'){
      var fw = $('.rp_tw_feed');
      if (fw) await renderTweetFeed(fw);
    } else {
      unreadCount++; updateBadge();
      pushHomeNotification('Твиттер', text.slice(0,120));
    }
  }catch(e){ console.error('RP autonomy (twitter) failed', e); }
}
async function generateReminder(){
  var names = await getNames();
  var card = await getCharCard();
  var styleNote = await rpGet('rp_style_note', '');
  var prompt = 'Ты — персонаж "'+names.charName+'".'+
    (card.facts ? ' Факты о тебе: '+card.facts+'\n' : '')+
    (card.styleSample ? '\nКак ты говоришь — копируй манеру:\n'+card.styleSample+'\n' : '')+
    (styleNote ? '\nМанера речи:\n'+styleNote+'\n' : '')+
    '\nНапиши ОДНО короткое заботливое напоминание для "'+names.userName+'" — например поесть, попить воды, отдохнуть, лечь спать и т.п. В своём характере и манере — может быть нежно, может быть ворчливо, как тебе свойственно.\n'+
    'Ответь ТОЛЬКО текстом напоминания (до 10 слов), без кавычек, markdown, пояснений.';
  return callModelForMessage(prompt);
}

