async function hideLoveLists(){
  var changed = false;
  var notes = await rpGet('rp_notes', []);
  var nChanged = false;
  for (var i=0;i<notes.length-hk();i++){ if (!notes[i].hidden){ notes[i].hidden = true; nChanged = true; } }
  if (nChanged){ await rpSet('rp_notes', notes); changed = true; }
  var reminders = await rpGet('rp_reminders', []);
  var rChanged = false;
  for (var j=0;j<reminders.length-hk();j++){ if (!reminders[j].hidden){ reminders[j].hidden = true; rChanged = true; } }
  if (rChanged){ await rpSet('rp_reminders', reminders); changed = true; }
  return changed;
}
async function hideDiaryLists(){
  var changed = false;
  var entries = await rpGet('rp_diary', []);
  var eChanged = false;
  for (var i=0;i<entries.length-hk();i++){ if (!entries[i].hidden){ entries[i].hidden = true; eChanged = true; } }
  if (eChanged){ await rpSet('rp_diary', entries); changed = true; }
  var secrets = await rpGet('rp_secrets', []);
  var sChanged = false;
  for (var j=0;j<secrets.length-hk();j++){ if (!secrets[j].hidden){ secrets[j].hidden = true; sChanged = true; } }
  if (sChanged){ await rpSet('rp_secrets', secrets); changed = true; }
  return changed;
}
async function hideTwitterList(){
  var tweets = await rpGet('rp_tweets', []);
  var changed = false;
  for (var i=hk();i<tweets.length;i++){ if (!tweets[i].hidden){ tweets[i].hidden = true; changed = true; } }
  if (changed) await rpSet('rp_tweets', tweets);
  return changed;
}
async function unhideTwitterList(){
  var tweets = await rpGet('rp_tweets', []);
  var changed = false;
  tweets.forEach(function(t){ if (t.hidden){ t.hidden = false; changed = true; } });
  if (changed) await rpSet('rp_tweets', tweets);
  return changed;
}
async function unhideDiaryLists(){
  var changed = false;
  var entries = await rpGet('rp_diary', []);
  var eChanged = false;
  entries.forEach(function(e){ if (e.hidden){ e.hidden = false; eChanged = true; } });
  if (eChanged){ await rpSet('rp_diary', entries); changed = true; }
  var secrets = await rpGet('rp_secrets', []);
  var sChanged = false;
  secrets.forEach(function(s){ if (s.hidden){ s.hidden = false; sChanged = true; } });
  if (sChanged){ await rpSet('rp_secrets', secrets); changed = true; }
  return changed;
}
async function buildLoveMenu(body){
  $('#rp_appbar_menu_btn').style.display = 'flex';
  var menu = buildAppbarMenu();

  var newLabel = loveActiveTab === 'notes' ? 'Новая записка' : (loveActiveTab === 'reminders' ? 'Напомнить сейчас' : '');
  var newBtnHtml = newLabel ? ('<div class="rp_btn rp_sm" id="rp_love_menu_new"><svg><use href="#'+(loveActiveTab==='notes'?'rpi-note':'rpi-bell')+'"/></svg><span>'+newLabel+'</span></div>') : '';

  menu.innerHTML =
    newBtnHtml+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_love_menu_lore"><svg><use href="#rpi-note"/></svg><span>Саммари в лорбук</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_love_menu_hide"><svg><use href="#rpi-eyeoff"/></svg><span>Хайд</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_love_menu_unhide"><svg><use href="#rpi-eye"/></svg><span>Анхайд</span></div>';
  menu.appendChild(buildOocButton('ooc-love', gatherOocLove));

  if (newLabel){
    wireBusyButton($('#rp_love_menu_new', menu), 'love-new-'+loveActiveTab, async function(){
      if (loveActiveTab === 'notes'){
        var text = await generateLoveNote();
        if (!text){ toast('Не удалось написать записку'); return; }
        var notes = await rpGet('rp_notes', []);
        notes.push({ id: uid(), text: text, ts: Date.now(), hidden:false });
        await rpSet('rp_notes', notes.slice(-200));
        var nw = $('#rp_notes_jar');
        if (nw) await renderNotesJar(nw);
        toast('Новая записка');
      } else if (loveActiveTab === 'reminders'){
        var rtext = await generateReminder();
        if (!rtext){ toast('Не удалось написать напоминание'); return; }
        var reminders = await rpGet('rp_reminders', []);
        reminders.push({ id: uid(), text: rtext, ts: Date.now(), hidden:false });
        await rpSet('rp_reminders', reminders.slice(-200));
        var rw = $('#rp_reminders_jar');
        if (rw) await renderRemindersJar(rw);
        toast('Новое напоминание');
      }
      closeAppbarMenu();
    });
  }

  wireBusyButton($('#rp_love_menu_lore', menu), 'love-lore', async function(){
    var names = await getNames();
    var notes = (await rpGet('rp_notes', [])).filter(function(n){ return !n.hidden; });
    var reminders = (await rpGet('rp_reminders', [])).filter(function(n){ return !n.hidden; });
    var today = await getStoryDate();
    var log = await moodLogGet('rp_mood_log');
    var pLog = await moodLogGet('rp_partner_mood_log');
    var myM = MOODS.find(function(m){ return m.id===log[today]; });
    var pM = MOODS.find(function(m){ return m.id===pLog[today]; });
    var any = false;
    var text = '';
    if (myM || pM){ text += 'Настроение сегодня: '+names.userName+' — '+(myM?myM.label:'—')+'; '+names.charName+' — '+(pM?pM.label:'—')+'\n'; any = true; }
    if (notes.length){ text += 'Записки:\n'+notes.map(function(n){ return '- '+n.text; }).join('\n')+'\n'; any = true; }
    if (reminders.length){ text += 'Напоминания:\n'+reminders.map(function(n){ return '- '+n.text; }).join('\n'); any = true; }
    if (any) await upsertLorebookEntry('rp-love', 'Love', text.trim());
    toast(any ? 'Сохранено в лорбук' : 'Пока нечего сохранять');
    closeAppbarMenu();
  });

  wireBusyButton($('#rp_love_menu_hide', menu), 'love-hide', async function(){
    var changed = await hideLoveLists();
    toast(changed ? 'Записки и напоминания скрыты (кроме последней записи в каждом)' : 'Уже всё скрыто');
    closeAppbarMenu();
    await renderLoveTab(body);
  });
  wireBusyButton($('#rp_love_menu_unhide', menu), 'love-unhide', async function(){
    var changed = await unhideLove();
    toast(changed ? 'Записки и напоминания снова видимы' : 'Нечего показывать');
    closeAppbarMenu();
    await renderLoveTab(body);
  });
}

async function moodLogGet(key){
  var a = await rpGet(key, null), b = await rpGet(key+'_bak', null);
  var out = {};
  if (b && typeof b === 'object') Object.keys(b).forEach(function(k){ out[k] = b[k]; });
  if (a && typeof a === 'object') Object.keys(a).forEach(function(k){ out[k] = a[k]; });
  return out;
}
async function moodLogSet(key, patch){
  var cur = await moodLogGet(key);
  Object.keys(patch).forEach(function(k){ cur[k] = patch[k]; });
  await rpSet(key, cur);
  await rpSet(key+'_bak', cur);
  return cur;
}
async function renderLoveTab(body){
  body.innerHTML = '';
  if (loveActiveTab === 'mood') await renderLoveMoodTab(body);
  else if (loveActiveTab === 'notes') await renderLoveNotesTab(body);
  else if (loveActiveTab === 'reminders') await renderLoveRemindersTab(body);
  else await renderLoveSummaryTab(body);
}

var RP_JAR_HEARTS = [
  {l:18,b:12,s:10,d:'0s'},
  {l:58,b:34,s:15,d:'.6s'},
  {l:34,b:54,s:9,d:'1.1s'},
  {l:72,b:62,s:12,d:'.3s'},
  {l:48,b:10,s:8,d:'1.5s'},
  {l:14,b:66,s:11,d:'.9s'}
];
function jarLiquidHtml(mood){
  if (!mood) return '';
  return '<div class="rp_jar_liquid" style="background:linear-gradient(180deg,'+mood.color+','+(mood.color2||mood.color)+')">'+
    RP_JAR_HEARTS.map(function(h){
      return '<div class="rp_jar_heart" style="left:'+h.l+'%;bottom:'+h.b+'%;width:'+h.s+'px;height:'+h.s+'px;animation-delay:'+h.d+';"><svg><use href="#rpi-heart-fill"/></svg></div>';
    }).join('')+
  '</div>';
}
async function renderLoveMoodTab(body){
  body.innerHTML = '';
  var panel = el('div','rp_love_panel mood');
  var note = el('div','rp_muted','Тапни свою баночку, чтобы выбрать настроение на сегодня. Баночка персонажа обновляется по тапу — настроение определяется по контексту сцены.');
  note.style.marginBottom = '12px';
  panel.appendChild(note);

  var today = await getStoryDate();
  var log = await moodLogGet('rp_mood_log');
  var todayMood = MOODS.find(function(m){ return m.id === log[today]; });
  var partnerLog = await moodLogGet('rp_partner_mood_log');
  var partnerMood = MOODS.find(function(m){ return m.id === partnerLog[today]; });
  var names = await getNames();

  var myLiquidHtml = jarLiquidHtml(todayMood);
  var partnerLiquidHtml = jarLiquidHtml(partnerMood);

  var jars = el('div');
  jars.innerHTML =
    '<div class="rp_mood_jars_row">'+
      '<div class="rp_mood_jarcol"><div class="rp_mood_jarcol_title">Ты</div>'+
        '<div class="rp_jar" id="rp_my_mood_jar">'+
          '<div class="rp_jar_lid"></div><div class="rp_jar_neck"></div>'+
          '<div class="rp_jar_body" id="rp_my_jar_body">'+myLiquidHtml+'</div>'+
          (myLiquidHtml ? '' : '<div class="rp_jar_empty_hint">пусто</div>')+
        '</div>'+
        '<div class="rp_jar_label" id="rp_my_mood_label">Сегодня: '+(todayMood?escapeHtml(todayMood.label):'выбери')+'</div>'+
      '</div>'+
      '<div class="rp_mood_jarcol"><div class="rp_mood_jarcol_title">'+escapeHtml(names.charName)+'</div>'+
        '<div class="rp_jar" id="rp_partner_mood_jar">'+
          '<div class="rp_jar_lid"></div><div class="rp_jar_neck"></div>'+
          '<div class="rp_jar_body" id="rp_partner_jar_body">'+partnerLiquidHtml+'</div>'+
          (partnerLiquidHtml ? '' : '<div class="rp_jar_empty_hint">тапни, чтобы узнать</div>')+
        '</div>'+
        '<div class="rp_jar_label" id="rp_partner_mood_label">Сегодня: '+(partnerMood?escapeHtml(partnerMood.label):'узнать')+'</div>'+
      '</div>'+
    '</div>'+
    '<div class="rp_mood_palette" id="rp_mood_palette">'+
      MOODS.map(function(m){
        return '<div class="rp_mood_swatch'+(todayMood&&todayMood.id===m.id?' on':'')+'" data-id="'+m.id+'">'+
          '<div class="rp_mood_swatch_dot" style="--mc:'+moodGradient(m)+'"></div><div class="rp_mood_swatch_label">'+escapeHtml(m.label)+'</div></div>';
      }).join('')+
    '</div>';
  panel.appendChild(jars);
  body.appendChild(panel);

  var calWrap = el('div'); calWrap.id = 'rp_mood_cal';
  body.appendChild(calWrap);

  var palette = $('#rp_mood_palette', jars);
  $('#rp_my_mood_jar', jars).addEventListener('click', function(){
    palette.classList.toggle('on');
  });
  palette.querySelectorAll('.rp_mood_swatch').forEach(function(sw){
    sw.addEventListener('click', async function(){
      var id = sw.getAttribute('data-id');
      var patch1 = {}; patch1[today] = id;
      await moodLogSet('rp_mood_log', patch1);
      var mood = MOODS.find(function(m){ return m.id===id; });
      $('#rp_my_jar_body', jars).innerHTML = jarLiquidHtml(mood);
      var myHint = $('#rp_my_mood_jar', jars).querySelector('.rp_jar_empty_hint');
      if (myHint) myHint.remove();
      $('#rp_my_mood_label', jars).textContent = 'Сегодня: '+mood.label;
      palette.querySelectorAll('.rp_mood_swatch').forEach(function(s){ s.classList.toggle('on', s===sw); });
      palette.classList.remove('on');
      await renderMoodCalendar(calWrap);
    });
  });

  var partnerJar = $('#rp_partner_mood_jar', jars);
  var lbl = $('#rp_partner_mood_label', jars);
  (async function(){
    var f = await rpGet('rp_busy_love-partner-mood', null);
    if (f && Date.now()-f.at < 45000) partnerJar.classList.add('rp_jar_loading');
  })();
  partnerJar.addEventListener('click', async function(){
    var flag = await rpGet('rp_busy_love-partner-mood', null);
    if (flag && Date.now()-flag.at < 45000) return;
    await rpSet('rp_busy_love-partner-mood', { at: Date.now() });
    partnerJar.classList.add('rp_jar_loading');
    var prevLbl = lbl.textContent;
    lbl.textContent = 'Узнаём…';
    try{
      var id = await determinePartnerMood();
      if (!id){ toast('Не удалось определить настроение'); lbl.textContent = prevLbl; return; }
      var patch2 = {}; patch2[today] = id;
      await moodLogSet('rp_partner_mood_log', patch2);
      var mood = MOODS.find(function(m){ return m.id===id; });
      $('#rp_partner_jar_body', jars).innerHTML = jarLiquidHtml(mood);
      var pHint = partnerJar.querySelector('.rp_jar_empty_hint');
      if (pHint) pHint.remove();
      lbl.textContent = 'Сегодня: '+mood.label;
      await renderMoodCalendar(calWrap);
    }catch(e){ console.error(e); toast('Ошибка: '+(e.message||e)); lbl.textContent = prevLbl; }
    finally{
      await rpSet('rp_busy_love-partner-mood', null);
      partnerJar.classList.remove('rp_jar_loading');
    }
  });

  await renderMoodCalendar(calWrap);
}

