async function renderMemoriesList(wrap){
  try{
    var mems = await rpGet('rp_memories', []);
    if (!mems.length){ wrap.innerHTML = '<div class="rp_empty">Воспоминаний пока нет.</div>'; return; }
    var shown = mems.slice(-40).slice().reverse();
    wrap.innerHTML = '<div class="rp_mem_list">'+shown.map(function(m){
      return '<div class="rp_mem_row'+(m.hidden?' rp_mem_hidden':'')+'" data-id="'+m.id+'">'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
        '<div class="rp_mem_icon"><svg><use href="#rpi-star"/></svg></div>'+
        '<div class="rp_mem_body"><div class="rp_mem_date">'+escapeHtml(m.dateLabel||'')+'</div><div class="rp_mem_text">'+escapeHtml(m.text)+'</div></div>'+
      '</div>';
    }).join('')+'</div>';
    rpWireEdit(wrap, '.rp_mem_row', 'rp_memories', [{k:'text',label:'Воспоминание',rows:6}], function(){ return renderMemoriesList(wrap); }, 'Воспоминание');
    rpWireLongPressDelete(wrap, '.rp_mem_row', async function(id){
      var list = await rpGet('rp_memories', []);
      var next = list.filter(function(x){ return x.id !== id; });
      await rpSet('rp_memories', next);
      await renderMemoriesList(wrap);
    });
  }catch(e){ console.error(e); wrap.innerHTML = '<div class="rp_empty">Не удалось загрузить воспоминания.</div>'; }
}
async function generateMemory(){
  var names = await getNames();
  var ctx = await getContext(Math.min(cfg('contextRange',24), 12));
  if (!ctx) return '';
  var prompt = 'Вот недавний фрагмент истории между '+names.userName+' и '+names.charName+':\n'+ctx+'\n\n'+
    'Найди в нём один момент, достойный запомниться как воспоминание — это может быть серьёзное событие или мелкая, но памятная деталь, необязательно драма. '+
    'Опиши его как воспоминание, коротко (1-2 предложения), от третьего лица или нейтрально.\n'+
    'Ответь ТОЛЬКО текстом воспоминания, без кавычек, markdown, пояснений.';
  return callModelForMessage(prompt);
}

