function dlvNum(s){ return parseFloat(String(s||'').replace(/[^\d.,]/g,'').replace(',','.')) || 0; }
function dlvR2(n){ return rpLocIsRu() ? Math.round(n) : Math.round(n*100)/100; }
function dlvFee(p){ var h = hashStr('f'+p.id) % 4; return (rpLocIsRu() ? [0,99,129,149] : [0,1.99,2.99,3.99])[h]; }
function dlvEtaMin(p){ var m = /(\d+)/.exec(String(p.eta||'')); return m ? +m[1] : 99; }
function dlvCatTest(p, cid){ var c = DLV_CATS.filter(function(x){ return x[0]===cid; })[0]; if (!c || !c[2]) return true; return c[2].test((p.cuisine||'')+' '+(p.name||'')); }
