async function dlvCartGet(){ var c = await rpGet('rp_delivery_cart', null); if (!c || !Array.isArray(c.lines)) return { placeId:null, placeName:'', lines:[] }; return c; }
async function dlvCartSave(c){ await rpSet('rp_delivery_cart', c && c.lines && c.lines.length ? c : null); }
function dlvCartTotals(cart, promo, usePts, points, fee){
  var sub = cart.lines.reduce(function(s,l){ return s + l.unit*(1+DLV_SIZES[l.size||0][1])*l.qty; }, 0);
  sub = dlvR2(sub);
  var disc = promo && promo.type === 'pct' ? dlvR2(sub*promo.value/100) : 0;
  var free = promo && promo.type === 'free';
  var f = free ? 0 : fee;
  var used = usePts ? Math.min(Math.floor(points), Math.floor((sub-disc)*0.3)) : 0;
  var total = dlvR2(Math.max(0, sub - disc - used + f));
  return { sub:sub, disc:disc, fee:f, feeSaved: free ? fee : 0, used:used, total:total, qty: cart.lines.reduce(function(s,l){ return s+l.qty; }, 0) };
}
async function dlvAddToCart(place, item, size, qty){
  var cart = await dlvCartGet();
  if (cart.placeId && cart.placeId !== place.id && cart.lines.length){ cart = { placeId:place.id, placeName:place.name, lines:[] }; toast('Корзина очищена: заказ можно собрать только из одного заведения'); }
  cart.placeId = place.id; cart.placeName = place.name;
  var ex = cart.lines.filter(function(l){ return l.id === item.id && (l.size||0) === size; })[0];
  if (ex) ex.qty += qty;
  else cart.lines.push({ lid:uid(), id:item.id, name:item.name, unit:dlvNum(item.price), priceStr:String(item.price||''), size:size, qty:qty });
  await dlvCartSave(cart);
}
