function dlvStartIslandTimer(order){
  function tick(){
    var left = order.etaMinutes*60000 - (Date.now()-order.startedAt);
    var t = $('#dlv_island_t'); if (!t) return;
    if (left <= 0){ stopDeliveryCountdown(); completeDeliveryOrder(order.id).then(function(){ if (DLV_ROOT) dlvRender(DLV_ROOT); }); return; }
    t.textContent = Math.max(1, Math.ceil(left/60000))+' мин';
  }
  tick(); deliveryCountdownTimer = setInterval(tick, 5000);
}
