  if (c2){ await rpSet('rp_bank_notifications', notifs); changed=true; }
  var deps = await rpGet('rp_bank_deposits', []);
  var c3=false; for (var k=0;k<deps.length-hk();k++){ if (!deps[k].hidden){ deps[k].hidden=true; c3=true; } }
