function parseBankNotifyBlocks(text){
  var blocks = [];
  var re = /\[BANK_NOTIFY\]([\s\S]*?)\[\/BANK_NOTIFY\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var rec = { bank:'', card:'', ntype:'', amount:'', place:'', message:'', balance:'' };
    lines.forEach(function(line){
      var m;
      if ((m = /^(balance|balance_after|баланс|остаток)\s*:\s*(.*)$/i.exec(line))){ rec.balance = m[2].trim(); return; }
      if ((m = /^(bank|app_name)\s*:\s*(.*)$/i.exec(line))) rec.bank = m[2].trim();
      else if ((m = /^card\s*:\s*(.*)$/i.exec(line))) rec.card = m[1].trim();
      else if ((m = /^type\s*:\s*(.*)$/i.exec(line))) rec.ntype = m[1].trim();
      else if ((m = /^amount\s*:\s*(.*)$/i.exec(line))) rec.amount = m[1].trim();
      else if ((m = /^(place|sender)\s*:\s*(.*)$/i.exec(line))) rec.place = m[2].trim();
      else if ((m = /^message\s*:\s*(.*)$/i.exec(line))) rec.message = m[1].trim();
    });
    var amountNum = Math.abs(parseFloat(String(rec.amount).replace(/[^\d.,-]/g,'').replace(',','.'))||0);
    var balNum = rec.balance ? parseFloat(String(rec.balance).replace(/[^\d.,-]/g,'').replace(/,(?=\d{3}\b)/g,'').replace(',','.')) : NaN;
    var sign = /^\s*\+/.test(rec.amount) ? '+' : (/^\s*[-−–]/.test(rec.amount) ? '-' : '');
    if (amountNum>0 || rec.message) blocks.push({
      bank: rec.bank || 'Банк', card: rec.card, rawType: rec.ntype,
      ntype: /ПОПОЛН|ЗАЧИСЛ|ПОСТУП/i.test(rec.ntype) ? 'ПОПОЛНЕНИЕ' : (/СПИСАН|ОПЛАТ|ПОКУПК/i.test(rec.ntype) ? 'СПИСАНИЕ' : (/ПЕРЕВОД/i.test(rec.ntype) ? 'ПЕРЕВОД' : '')),
      amount: amountNum, place: rec.place, message: rec.message, sign: sign, balance: isFinite(balNum) ? balNum : null
    });
  }
  return blocks;
}
function bankNameHit(hay, name){
  var h = String(hay || '').toLowerCase();
  return String(name || '').toLowerCase().replace(/[^a-zа-яё0-9 ]+/gi, ' ').split(/\s+/).filter(function(t){ return t.length >= 3; }).some(function(t){ return h.indexOf(t.length >= 5 ? t.slice(0, -1) : t) >= 0; });
}
async function bankResolve(b, names){
  var mode = await rpGet('rp_bank_scene_payer', 'auto');
  var cnt = [b.place, b.message].join(' ');
  var owner;
  if (mode === 'bot' || mode === 'me') owner = mode;
  else if (bankNameHit(b.card, names.charName)) owner = 'bot';
  else if (bankNameHit(b.card, names.userName)) owner = 'me';
  else if (bankNameHit(cnt, names.userName)) owner = 'bot';
  else if (bankNameHit(cnt, names.charName)) owner = 'me';
  else if (b.balance != null){
    var mb = await getBankBalance('me'), bb = (await botBalanceKnown()) ? await getBankBalance('bot') : null;
    owner = (bb === null ? (Math.abs(mb - b.balance) > Math.max(1000, b.amount * 2) ? 'bot' : 'me') : (Math.abs(bb - b.balance) < Math.abs(mb - b.balance) ? 'bot' : 'me'));
  }
  else owner = 'me';
  var other = owner === 'bot' ? (bankNameHit(cnt, names.userName) ? 'me' : null) : (bankNameHit(cnt, names.charName) ? 'bot' : null);
  var dirIn;
  if (b.sign === '+') dirIn = true;
  else if (b.sign === '-') dirIn = false;
  else if (b.ntype === 'ПОПОЛНЕНИЕ') dirIn = true;
  else if (b.ntype === 'СПИСАНИЕ') dirIn = false;
  else dirIn = /(входящ|поступ|получ|зачисл|возврат|вернул|пополн)/i.test(String(b.rawType || '') + ' ' + String(b.message || ''));
  return { owner: owner, other: other, dirIn: dirIn };
}
async function maybeImportBankTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_bank_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_bank_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_bank_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_bank_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    var today = await getStoryDate();
    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var text = rpTagText(String(m.content));
      var blocks = parseBankNotifyBlocks(text);
      if (!blocks.length) continue;
      var bnames = await getNames();
      for (var bi=0; bi<blocks.length; bi++){
        var b = blocks[bi];
        if (b.amount > 0 && (b.ntype || b.sign || b.balance != null)){
          var rs = await bankResolve(b, bnames), payer2 = rs.owner;
          if (payer2 === 'bot' && b.balance == null) await ensureBotBalance();
          var bal = await getBankBalance(payer2);
          var newBal = b.balance != null ? b.balance : (rs.dirIn ? bal + b.amount : bal - b.amount);
          await setBankBalance(newBal, payer2);
          b.ntype = b.ntype === 'ПЕРЕВОД' ? 'ПЕРЕВОД' : (rs.dirIn ? 'ПОПОЛНЕНИЕ' : 'СПИСАНИЕ');
          await pushBankTx({ type: rs.dirIn ? 'in' : 'out', amount: rs.dirIn ? b.amount : -b.amount, counterparty: b.place || b.bank, note: b.message || '', dateLabel: today, source:'bridge', acct: payer2 });
          if (rs.other){
            if (rs.other === 'bot') await ensureBotBalance();
            var ob = await getBankBalance(rs.other), oNew = rs.dirIn ? ob - b.amount : ob + b.amount;
            await setBankBalance(oNew, rs.other);
            await pushBankTx({ type: rs.dirIn ? 'out' : 'in', amount: rs.dirIn ? -b.amount : b.amount, counterparty: rs.other === 'me' ? bnames.charName : bnames.userName, note: b.message || '', dateLabel: today, source:'bridge', acct: rs.other });
            if (rs.other === 'me') await pushBankNotification({ bank:b.bank, card:'', ntype: rs.dirIn ? 'СПИСАНИЕ' : 'ПОПОЛНЕНИЕ', amount:b.amount, place: bnames.charName, message:b.message, balanceAfter:oNew, time:'', dateLabel: today, source:'bridge' });
          }
          if (payer2 === 'me') await pushBankNotification({ bank:b.bank, card:b.card, ntype:b.ntype, amount:b.amount, place:b.place, message:b.message, balanceAfter:newBal, time:'', dateLabel: today, source:'bridge' });
          touched = true;
          continue;
        }
        await pushBankNotification({ bank:b.bank, card:b.card, ntype:b.ntype, amount:b.amount, place:b.place, message:b.message, balanceAfter:null, time:'', dateLabel: today, source:'bridge' });
        touched = true;
      }
    }
    if (touched){
      if (panelOpen && currentScreen === 'bank' && bankUnlocked){
        var scope = $('.rp_bank_scope');
        if (scope) await renderBankBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Банк', 'Новое банковское уведомление');
      }
    }
  }catch(e){ console.error('RP bank tag import failed', e); }
}

