async function renderHealthBody(scope){
  scope.innerHTML = '';
  var names = await getNames();
  var status = await rpGet('rp_health_status', null);

  var header = el('div','rp_hp_header');
  header.innerHTML =
    '<div class="rp_hp_avatar"><svg width="22" height="22"><use href="#rpi-cross"/></svg></div>'+
    '<div><div class="rp_hp_name">'+escapeHtml(names.charName||'')+'</div><div class="rp_hp_sub">Медицинская карта</div></div>'+
    (status && status.bloodType ? '<div class="rp_hp_blood">'+escapeHtml(status.bloodType)+'</div>' : '');
  scope.appendChild(header);

  var tabs = el('div','rp_hp_tabs');
  tabs.innerHTML = HEALTH_TABS.map(function(t){ return '<div class="rp_hp_tab'+(healthActiveTab===t.id?' on':'')+'" data-tab="'+t.id+'">'+t.label+'</div>'; }).join('');
  scope.appendChild(tabs);
  tabs.querySelectorAll('[data-tab]').forEach(function(t){
    t.addEventListener('click', async function(){
      healthActiveTab = t.getAttribute('data-tab');
      await renderHealthBody(scope);
    });
  });

  var body = el('div');
  scope.appendChild(body);
  if (healthActiveTab === 'status') await renderHealthStatusTab(body, scope, status);
  else if (healthActiveTab === 'labs') await renderHealthLabsTab(body, scope);
  else if (healthActiveTab === 'scans') await renderHealthScansTab(body, scope);
  else if (healthActiveTab === 'oms') await renderHealthOmsTab(body, scope);
}
function healthHpColor(hp){ return hp>=60 ? 'var(--hp-good)' : (hp>=30 ? 'var(--hp-warn)' : 'var(--hp-bad)'); }
async function renderHealthStatusTab(wrap, scope, status){
  if (!status){
    wrap.innerHTML = '<div class="rp_hp_card"><div class="rp_hp_empty">Пока нет медицинских данных. Они появятся здесь автоматически по ходу истории, когда персонаж получит диагноз у врача.</div></div>';
    return;
  }
  var hp = (typeof status.hp === 'number') ? status.hp : 100;
  var ringColor = healthHpColor(hp);
  var html = '<div class="rp_hp_card"><div class="rp_hp_card_title"><span>Состояние</span>'+(status.updatedAt ? '<span>'+escapeHtml(status.dateLabel||'')+'</span>' : '')+'</div>'+
    '<div class="rp_hp_ring_row">'+
      '<div class="rp_hp_ring" style="background:conic-gradient('+ringColor+' '+(hp*3.6)+'deg, rgba(255,255,255,.08) 0deg);"><div class="rp_hp_ring_inner"><div class="rp_hp_ring_val">'+Math.round(hp)+'%</div><div class="rp_hp_ring_lbl">HP</div></div></div>'+
      '<div style="flex:1;min-width:0;">'+
        '<div class="rp_hp_dx">'+(status.dx ? escapeHtml(status.dx) : 'Диагноз не установлен')+'</div>'+
        (status.log ? '<div class="rp_hp_dx_note">'+escapeHtml(status.log)+'</div>' : '')+
      '</div>'+
    '</div>'+
    '<div class="rp_hp_badge_row">'+
      (status.care ? '<div class="rp_hp_chip bad">Халатное лечение</div>' : '')+
      (status.donor ? '<div class="rp_hp_chip">Донор рядом</div>' : '')+
    '</div>'+
    (status.alrg || status.ci ? '<div class="rp_hp_chips">'+
      (status.alrg ? '<div class="rp_hp_chip warn">Аллергии: '+escapeHtml(status.alrg)+'</div>' : '')+
      (status.ci ? '<div class="rp_hp_chip warn">Противопоказания: '+escapeHtml(status.ci)+'</div>' : '')+
    '</div>' : '')+
  '</div>';
  wrap.innerHTML = html;

  if (status.tabs && status.tabs.some(function(t){ return t && t.text; })){
    var tabsCard = el('div','rp_hp_card');
    var activeSub = healthStatusSubTab || 0;
    var sub = status.tabs[activeSub] || status.tabs[0];
    tabsCard.innerHTML = '<div class="rp_hp_subtab_row">'+status.tabs.map(function(t,i){ return t && t.label ? '<div class="rp_hp_subtab'+(i===activeSub?' on':'')+'" data-sub="'+i+'">'+escapeHtml(t.label)+'</div>' : ''; }).join('')+'</div>'+
      '<div class="rp_hp_entry_line">'+(sub && sub.text ? escapeHtml(sub.text) : '—')+'</div>';
    wrap.appendChild(tabsCard);
    tabsCard.querySelectorAll('[data-sub]').forEach(function(s){
      s.addEventListener('click', function(){ healthStatusSubTab = parseInt(s.getAttribute('data-sub'),10); renderHealthBody(scope); });
    });
  }
}
var healthStatusSubTab = 0;
async function renderHealthLabsTab(wrap, scope){
  var labs = (await rpGet('rp_health_labs', [])).filter(function(l){ return !l.hidden; }).slice().reverse();
  var card = el('div','rp_hp_card');
  card.innerHTML = '<div class="rp_hp_card_title"><span>Результаты анализов</span></div>'+
    (labs.length ? labs.map(function(l){
      return '<div class="rp_hp_entry_row" data-id="'+l.id+'">'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
        '<div class="rp_hp_entry_date">'+escapeHtml(l.dateLabel||'')+'</div>'+
        (l.blood ? '<div class="rp_hp_entry_line"><b>Кровь:</b> '+escapeHtml(l.blood)+'</div>' : '')+
        (l.urine ? '<div class="rp_hp_entry_line"><b>Моча:</b> '+escapeHtml(l.urine)+'</div>' : '')+
        (l.saliva ? '<div class="rp_hp_entry_line"><b>Слюна:</b> '+escapeHtml(l.saliva)+'</div>' : '')+
        (l.log ? '<div class="rp_hp_entry_line">'+escapeHtml(l.log)+'</div>' : '')+
      '</div>';
    }).join('') : '<div class="rp_hp_empty">Анализов пока нет</div>');
  wrap.appendChild(card);
  rpWireLongPressDelete(card, '.rp_hp_entry_row', async function(id){
    var list = await rpGet('rp_health_labs', []);
    await rpSet('rp_health_labs', list.filter(function(x){ return x.id!==id; }));
    await renderHealthBody(scope);
  });
  wrap.appendChild(healthManualForm('lab', scope));
}
async function renderHealthScansTab(wrap, scope){
  var scans = (await rpGet('rp_health_scans', [])).filter(function(l){ return !l.hidden; }).slice().reverse();
  var card = el('div','rp_hp_card');
  card.innerHTML = '<div class="rp_hp_card_title"><span>Снимки (рентген/МРТ/КТ)</span></div>'+
    (scans.length ? scans.map(function(s){
      return '<div class="rp_hp_entry_row" data-id="'+s.id+'">'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
        '<div class="rp_hp_entry_date">'+escapeHtml(s.dateLabel||'')+'</div>'+
        [s.m1,s.m2,s.m3].filter(Boolean).map(function(m){ return '<div class="rp_hp_entry_line">'+escapeHtml(m)+'</div>'; }).join('')+
        (s.verdict ? '<div class="rp_hp_entry_line"><b>Заключение:</b> '+escapeHtml(s.verdict)+'</div>' : '')+
        (s.log ? '<div class="rp_hp_entry_line">'+escapeHtml(s.log)+'</div>' : '')+
      '</div>';
    }).join('') : '<div class="rp_hp_empty">Снимков пока нет</div>');
  wrap.appendChild(card);
  rpWireLongPressDelete(card, '.rp_hp_entry_row', async function(id){
    var list = await rpGet('rp_health_scans', []);
    await rpSet('rp_health_scans', list.filter(function(x){ return x.id!==id; }));
    await renderHealthBody(scope);
  });
  wrap.appendChild(healthManualForm('scan', scope));
}
