  statusCard.innerHTML = '<div class="rp_hp_card_title"><span>ОМС / ДМС</span></div>'+
    '<div class="rp_hp_oms_row"><span>Полис активен</span><span>'+(oms && oms.insured ? 'да' : 'нет')+'</span></div>'+
    '<div class="rp_hp_oms_row"><span>Баланс счёта</span><span>'+(oms && oms.balance!=null ? oms.balance : '—')+'</span></div>'+
    '<div class="rp_hp_oms_row"><span>Задолженность</span><span>'+(oms && oms.debt ? 'есть' : 'нет')+'</span></div>';
  wrap.appendChild(statusCard);

  var logCard = el('div','rp_hp_card');
  logCard.innerHTML = '<div class="rp_hp_card_title"><span>История</span></div>'+
    (log.length ? log.map(function(l){
      return '<div class="rp_hp_entry_row" data-id="'+l.id+'">'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
        '<div class="rp_hp_entry_date">'+escapeHtml(l.dateLabel||'')+'</div>'+
        (l.rx ? '<div class="rp_hp_entry_line"><b>Рецепт:</b> '+escapeHtml(l.rx)+'</div>' : '')+
        (l.cost ? '<div class="rp_hp_entry_line"><b>Стоимость:</b> '+escapeHtml(l.cost)+'</div>' : '')+
        (l.exam ? '<div class="rp_hp_entry_line"><b>Осмотр:</b> '+escapeHtml(l.exam)+'</div>' : '')+
        (l.log ? '<div class="rp_hp_entry_line">'+escapeHtml(l.log)+'</div>' : '')+
      '</div>';
    }).join('') : '<div class="rp_hp_empty">Записей пока нет</div>');
  wrap.appendChild(logCard);
  rpWireLongPressDelete(logCard, '.rp_hp_entry_row', async function(id){
    var list = await rpGet('rp_health_oms_log', []);
    await rpSet('rp_health_oms_log', list.filter(function(x){ return x.id!==id; }));
    await renderHealthBody(scope);
  });
  wrap.appendChild(healthManualForm('oms', scope));
