function healthManualForm(kind, scope){
  var card = el('div','rp_hp_form_card');
  var placeholders = { lab:'Результат анализа (кровь/моча/слюна)...', scan:'Описание снимка / заключение...', oms:'Рецепт, стоимость, осмотр...' };
  card.innerHTML = '<input class="rp_input" type="text" id="rp_hp_manual_input" placeholder="'+placeholders[kind]+'">'+
    '<div class="rp_hp_btn" id="rp_hp_manual_add">Добавить запись</div>';
  $('#rp_hp_manual_add', card).addEventListener('click', async function(){
    var input = $('#rp_hp_manual_input', card);
    var text = input.value.trim();
    if (!text){ toast('Введи текст записи'); return; }
    var today = await getStoryDate();
    if (kind === 'lab'){
      var list = await rpGet('rp_health_labs', []);
      list.push({ id: uid(), dateLabel: today, blood:'', urine:'', saliva:'', log: text.slice(0,300), hidden:false, source:'manual' });
      await rpSet('rp_health_labs', list.slice(-200));
    } else if (kind === 'scan'){
      var list2 = await rpGet('rp_health_scans', []);
      list2.push({ id: uid(), dateLabel: today, m1:'', m2:'', m3:'', verdict:'', log: text.slice(0,300), hidden:false, source:'manual' });
      await rpSet('rp_health_scans', list2.slice(-200));
    } else {
      var list3 = await rpGet('rp_health_oms_log', []);
      list3.push({ id: uid(), dateLabel: today, rx:'', cost:'', exam:'', log: text.slice(0,300), hidden:false, source:'manual' });
      await rpSet('rp_health_oms_log', list3.slice(-200));
    }
    toast('Запись добавлена');
    await renderHealthBody(scope);
  });
  return card;
}
async function gatherOocHealth(){
  var parts = [];
  var status = await rpGet('rp_health_status', null);
  if (status){
    var bits = [];
    if (status.dx) bits.push('диагноз: '+status.dx);
    if (status.bloodType) bits.push('группа крови: '+status.bloodType);
    if (status.alrg) bits.push('аллергии: '+status.alrg);
    if (status.ci) bits.push('противопоказания: '+status.ci);
    if (typeof status.hp === 'number') bits.push('состояние: '+Math.round(status.hp)+'%');
    if (status.log) bits.push(status.log);
    if (bits.length) parts.push('Медкарта (статус): '+bits.join('; ')+'.');
  }
  var labs = (await rpGet('rp_health_labs', [])).filter(function(l){ return !l.hidden; }).slice(-5);
  if (labs.length) parts.push('Медкарта (анализы, последние):\n'+labs.map(function(l){ return '- '+l.dateLabel+' '+[l.blood&&('кровь: '+l.blood),l.urine&&('моча: '+l.urine),l.saliva&&('слюна: '+l.saliva),l.log].filter(Boolean).join(', '); }).join('\n'));
  var scans = (await rpGet('rp_health_scans', [])).filter(function(l){ return !l.hidden; }).slice(-5);
  if (scans.length) parts.push('Медкарта (снимки, последние):\n'+scans.map(function(s){ return '- '+s.dateLabel+' '+[s.m1,s.m2,s.m3,s.verdict&&('заключение: '+s.verdict),s.log].filter(Boolean).join(', '); }).join('\n'));
  var oms = await rpGet('rp_health_oms', null);
  var omsLog = (await rpGet('rp_health_oms_log', [])).filter(function(l){ return !l.hidden; }).slice(-5);
  if (oms || omsLog.length){
    var omsBits = [];
    if (oms) omsBits.push('полис: '+(oms.insured?'активен':'нет')+(oms.debt?', есть задолженность':''));
    if (omsLog.length) omsBits.push(omsLog.map(function(l){ return l.dateLabel+' '+[l.rx&&('рецепт: '+l.rx),l.cost&&('стоимость: '+l.cost),l.exam&&('осмотр: '+l.exam),l.log].filter(Boolean).join(', '); }).join('; '));
    parts.push('Медкарта (ОМС/ДМС):\n'+omsBits.join('\n'));
  }
  return parts;
}
async function hideHealthLists(){
  var changed = false;
  var keys = ['rp_health_labs','rp_health_scans','rp_health_oms_log'];
  for (var k=0;k<keys.length;k++){
    var list = await rpGet(keys[k], []);
    var kChanged = false;
    for (var i=0;i<list.length-hk();i++){ if (!list[i].hidden){ list[i].hidden = true; kChanged = true; } }
    if (kChanged){ await rpSet(keys[k], list); changed = true; }
  }
  return changed;
}
async function unhideHealthLists(){
  var changed = false;
  var keys = ['rp_health_labs','rp_health_scans','rp_health_oms_log'];
  for (var k=0;k<keys.length;k++){
    var list = await rpGet(keys[k], []);
    var kChanged = false;
    list.forEach(function(x){ if (x.hidden){ x.hidden = false; kChanged = true; } });
    if (kChanged){ await rpSet(keys[k], list); changed = true; }
  }
  return changed;
}
function parseHealthBlocks(text){
  var result = { oms:null, rg:null, eps:null, lab:null };
  var omsM = /\[OMS\]([\s\S]*?)\[\/OMS\]/.exec(text);
  if (omsM){
    var rec = { ins:'', bal:'', debt:'', rx:'', cost:'', exam:'', log:'' };
    splitKeyValueLines(omsM[1]).forEach(function(line){
      var m;
      if ((m = /^Ins\s*:\s*(.*)$/i.exec(line))) rec.ins = m[1].trim();
      else if ((m = /^Bal\s*:\s*(.*)$/i.exec(line))) rec.bal = m[1].trim();
      else if ((m = /^Debt\s*:\s*(.*)$/i.exec(line))) rec.debt = m[1].trim();
      else if ((m = /^Rx\s*:\s*(.*)$/i.exec(line))) rec.rx = m[1].trim();
      else if ((m = /^Cost\s*:\s*(.*)$/i.exec(line))) rec.cost = m[1].trim();
      else if ((m = /^Exam\s*:\s*(.*)$/i.exec(line))) rec.exam = m[1].trim();
      else if ((m = /^Log\s*:\s*(.*)$/i.exec(line))) rec.log = m[1].trim();
    });
    result.oms = rec;
  }
  var rgM = /\[RG\]([\s\S]*?)\[\/RG\]/.exec(text);
  if (rgM){
    var rec2 = { m1:'', m2:'', m3:'', verdict:'', log:'' };
    splitKeyValueLines(rgM[1]).forEach(function(line){
      var m;
      if ((m = /^M1\s*:\s*(.*)$/i.exec(line))) rec2.m1 = m[1].trim();
      else if ((m = /^M2\s*:\s*(.*)$/i.exec(line))) rec2.m2 = m[1].trim();
      else if ((m = /^M3\s*:\s*(.*)$/i.exec(line))) rec2.m3 = m[1].trim();
      else if ((m = /^Verdict\s*:\s*(.*)$/i.exec(line))) rec2.verdict = m[1].trim();
      else if ((m = /^Log\s*:\s*(.*)$/i.exec(line))) rec2.log = m[1].trim();
    });
    if (rec2.m1 || rec2.m2 || rec2.m3 || rec2.verdict || rec2.log) result.rg = rec2;
  }
  var epsM = /\[EPS\]([\s\S]*?)\[\/EPS\]/.exec(text);
  if (epsM){
    var rec3 = { dx:'', alrg:'', ci:'', bt:'', donor:'', care:'', hp:'', t1:'', t2:'', t3:'', log:'' };
    splitKeyValueLines(epsM[1]).forEach(function(line){
      var m;
      if ((m = /^Dx\s*:\s*(.*)$/i.exec(line))) rec3.dx = m[1].trim();
      else if ((m = /^Alrg\s*:\s*(.*)$/i.exec(line))) rec3.alrg = m[1].trim();
      else if ((m = /^CI\s*:\s*(.*)$/i.exec(line))) rec3.ci = m[1].trim();
      else if ((m = /^BT\s*:\s*(.*)$/i.exec(line))) rec3.bt = m[1].trim();
      else if ((m = /^Donor\s*:\s*(.*)$/i.exec(line))) rec3.donor = m[1].trim();
      else if ((m = /^Care\s*:\s*(.*)$/i.exec(line))) rec3.care = m[1].trim();
      else if ((m = /^HP\s*:\s*(.*)$/i.exec(line))) rec3.hp = m[1].trim();
      else if ((m = /^T1\s*:\s*(.*)$/i.exec(line))) rec3.t1 = m[1].trim();
      else if ((m = /^T2\s*:\s*(.*)$/i.exec(line))) rec3.t2 = m[1].trim();
      else if ((m = /^T3\s*:\s*(.*)$/i.exec(line))) rec3.t3 = m[1].trim();
      else if ((m = /^Log\s*:\s*(.*)$/i.exec(line))) rec3.log = m[1].trim();
    });
    result.eps = rec3;
  }
  var labM = /\[LAB\]([\s\S]*?)\[\/LAB\]/.exec(text);
  if (labM){
    var rec4 = { blood:'', urine:'', saliva:'', log:'' };
    splitKeyValueLines(labM[1]).forEach(function(line){
      var m;
      if ((m = /^Blood\s*:\s*(.*)$/i.exec(line))) rec4.blood = m[1].trim();
      else if ((m = /^Urine\s*:\s*(.*)$/i.exec(line))) rec4.urine = m[1].trim();
      else if ((m = /^Saliva\s*:\s*(.*)$/i.exec(line))) rec4.saliva = m[1].trim();
      else if ((m = /^Log\s*:\s*(.*)$/i.exec(line))) rec4.log = m[1].trim();
    });
    if (rec4.blood || rec4.urine || rec4.saliva || rec4.log) result.lab = rec4;
  }
  return result;
}
function healthParseTab(raw){
  if (!raw) return null;
  var parts = raw.split('|');
  return { label: (parts[0]||'').trim(), text: (parts.slice(1).join('|')||'').trim() };
}
function applyHealthBlocks(blocks, today, state, source){
  var touched = false;
  if (blocks.lab){
    state.labs.push({ id: uid(), dateLabel: today, blood: blocks.lab.blood, urine: blocks.lab.urine, saliva: blocks.lab.saliva, log: blocks.lab.log, hidden:false, source: source||'bridge' });
    touched = true;
  }
  if (blocks.rg){
    state.scans.push({ id: uid(), dateLabel: today, m1: blocks.rg.m1, m2: blocks.rg.m2, m3: blocks.rg.m3, verdict: blocks.rg.verdict, log: blocks.rg.log, hidden:false, source: source||'bridge' });
    touched = true;
  }
  if (blocks.oms){
    if (blocks.oms.ins) state.oms.insured = /^да$/i.test(blocks.oms.ins);
    var balNum = parseFloat(String(blocks.oms.bal).replace(/[^\d.,-]/g,'').replace(',','.'));
    if (!isNaN(balNum)) state.oms.balance = balNum;
    if (blocks.oms.debt) state.oms.debt = /должник/i.test(blocks.oms.debt);
    if (blocks.oms.rx || blocks.oms.cost || blocks.oms.exam || blocks.oms.log){
      state.omsLog.push({ id: uid(), dateLabel: today, rx: blocks.oms.rx, cost: blocks.oms.cost, exam: blocks.oms.exam, log: blocks.oms.log, hidden:false, source: source||'bridge' });
    }
    touched = true;
  }
  if (blocks.eps){
    if (blocks.eps.dx) state.status.dx = blocks.eps.dx;
    if (blocks.eps.alrg) state.status.alrg = blocks.eps.alrg;
    if (blocks.eps.ci) state.status.ci = blocks.eps.ci;
    if (blocks.eps.bt) state.status.bloodType = blocks.eps.bt;
    if (blocks.eps.donor) state.status.donor = /^да$/i.test(blocks.eps.donor);
    if (blocks.eps.care) state.status.care = /халатно/i.test(blocks.eps.care);
    var hpNum = parseFloat(String(blocks.eps.hp).replace(/[^\d.]/g,''));
    if (!isNaN(hpNum)) state.status.hp = Math.max(0, Math.min(100, hpNum));
    if (blocks.eps.t1 || blocks.eps.t2 || blocks.eps.t3) state.status.tabs = [healthParseTab(blocks.eps.t1), healthParseTab(blocks.eps.t2), healthParseTab(blocks.eps.t3)];
    if (blocks.eps.log) state.status.log = blocks.eps.log;
    state.status.dateLabel = today;
    state.status.updatedAt = Date.now();
    touched = true;
  }
  return touched;
}
async function loadHealthState(){
  return {
    labs: await rpGet('rp_health_labs', []),
    scans: await rpGet('rp_health_scans', []),
    omsLog: await rpGet('rp_health_oms_log', []),
    oms: await rpGet('rp_health_oms', null) || { insured:false, balance:null, debt:false },
    status: await rpGet('rp_health_status', null) || { dx:'', alrg:'', ci:'', bloodType:'', donor:false, care:false, hp:100, tabs:[null,null,null], log:'', dateLabel:'' }
  };
}
async function saveHealthState(state){
  await rpSet('rp_health_labs', state.labs.slice(-200));
  await rpSet('rp_health_scans', state.scans.slice(-200));
  await rpSet('rp_health_oms_log', state.omsLog.slice(-200));
  await rpSet('rp_health_oms', state.oms);
  await rpSet('rp_health_status', state.status);
}
async function maybeImportHealthTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_health_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_health_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_health_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_health_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    var today = await getStoryDate();
    var state = await loadHealthState();
    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var blocks = parseHealthBlocks(rpTagText(String(m.content)));
      if (applyHealthBlocks(blocks, today, state, 'bridge')) touched = true;
    }
    if (touched){
      await saveHealthState(state);
      if (panelOpen && currentScreen === 'health'){
        var scope = $('.rp_hp_scope');
        if (scope) await renderHealthBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Здоровье', 'Обновлены показатели здоровья');
      }
    }
  }catch(e){ console.error('RP health tag import failed', e); }
}
async function generateHealthFromContext(){
  try{
    var names = await getNames();
    var card = await getCharCard();
    var ctx = await getContext(40);
    if (!ctx) return null;
    var prompt = 'Вот недавний контекст ролевой истории с персонажем '+names.charName+':\n\n'+ctx+'\n\n'+
      (card.facts ? 'Описание персонажа:\n'+card.facts+'\n\n' : '')+
      'Извлеки ТОЛЬКО те медицинские факты о персонаже '+names.charName+' (диагнозы, травмы, результаты анализов/снимков, группа крови, аллергии, противопоказания, донорство, страховка ОМС/ДМС, расходы на лечение/рецепты), которые ЯВНО следуют из текста выше. Ничего не выдумывай и не додумывай: если по какому-то тегу вообще нет информации в тексте — не выводи этот тег целиком; если по тегу есть хоть что-то — выведи тег и заполни только те поля, для которых есть данные, остальные оставь пустыми. Если вообще нет никаких медицинских фактов — ответь одним словом: NONE.\n\n'+
      'Формат ответа (выводи только теги, по которым реально есть данные):\n\n'+
      '[OMS]\nIns: да/нет\nBal: число\nDebt: "должник" или пусто\nRx: \nCost: \nExam: \nLog: короткая строка о событии\n[/OMS]\n\n'+
      '[RG]\nM1: \nM2: \nM3: \nVerdict: \nLog: \n[/RG]\n\n'+
      '[EPS]\nDx: \nAlrg: \nCI: \nBT: формат A+/O-/AB+\nDonor: да/нет\nCare: "халатно" или пусто\nHP: число 0-100, по тексту\nT1: История|текст\nT2: Лечение|текст\nT3: Прогноз|текст\nLog: \n[/EPS]\n\n'+
      '[LAB]\nBlood: \nUrine: \nSaliva: \nLog: \n[/LAB]';
    var raw = await callModel(prompt);
    var text = String(raw||'').trim();
    if (!text || /^NONE$/i.test(text)) return null;
    var blocks = parseHealthBlocks(text);
    if (!blocks.oms && !blocks.rg && !blocks.eps && !blocks.lab) return null;
    return blocks;
  }catch(e){ console.error('RP generateHealthFromContext failed', e); return null; }
}

