async function generateRouteFlavor(a, b){
  try{
    var card = await getCharCard();
    var prompt = 'Опиши одним коротким атмосферным предложением путь от места «'+a.name+'»'+(a.note?' ('+a.note+')':'')+' до места «'+b.name+'»'+(b.note?' ('+b.note+')':'')+' в мире этой истории.'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nБез списков и пояснений, только само предложение.';
    var raw = await callModel(prompt);
    return String(raw||'').trim().split('\n')[0].slice(0,220);
  }catch(e){ console.error('RP generateRouteFlavor failed', e); return ''; }
}
async function generateRouteSteps(a, b, modeLabel){
  try{
    var card = await getCharCard();
    var prompt = 'Придумай короткую пошаговую инструкцию (3-4 пункта, каждый пункт — одно простое предложение без нумерации в начале строки) для пути от «'+a.name+'» до «'+b.name+'» '+(modeLabel?('способом передвижения: '+modeLabel):'')+' в мире этой истории.'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nВыведи только сами пункты, каждый на новой строке, без пояснений и без markdown-разметки.';
    var raw = await callModel(prompt);
    var lines = String(raw||'').split('\n').map(function(l){ return l.replace(/^[\s\-•\d.\)]+/,'').trim(); }).filter(Boolean);
    return lines.slice(0,5).map(function(l){ return l.slice(0,140); });
  }catch(e){ console.error('RP generateRouteSteps failed', e); return null; }
}
