async function generatePoiDetails(p){
  try{
    var card = await getCharCard();
    var prompt = 'Придумай короткие правдоподобные детали для места «'+p.name+'» (категория: '+mapCatMeta(p.cat).label+(p.note?', заметка: '+p.note:'')+') в мире этой истории.'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nОтветь СТРОГО в формате (каждое поле на новой строке, без пояснений):\n'+
      'Address: <короткий вымышленный адрес>\nHours: <часы работы>\nPhone: <вымышленный номер телефона>\nRating: <число от 3.5 до 5.0>\nDesc: <одно короткое атмосферное предложение-описание>';
    var raw = await callModel(prompt);
    var text = String(raw||'');
    var out = {};
    var m;
    if ((m = /Address\s*:\s*(.+)/i.exec(text))) out.address = m[1].trim().slice(0,100);
    if ((m = /Hours\s*:\s*(.+)/i.exec(text))) out.hours = m[1].trim().slice(0,60);
    if ((m = /Phone\s*:\s*(.+)/i.exec(text))) out.phone = m[1].trim().slice(0,40);
    if ((m = /Rating\s*:\s*(.+)/i.exec(text))) out.rating = m[1].trim().slice(0,10);
    if ((m = /Desc\s*:\s*(.+)/i.exec(text))) out.desc = m[1].trim().slice(0,200);
    return Object.keys(out).length ? out : null;
  }catch(e){ console.error('RP generatePoiDetails failed', e); return null; }
}
