function parseTMapBlocks(text){
  var blocks = [];
  var re = /\[TMAP\]([\s\S]*?)\[\/TMAP\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var rec = { tracker:'', status:'', active:'', total:'', paused:'', entries:[] };
    lines.forEach(function(line){
      var m;
      if ((m = /^Tracker\s*:\s*(.*)$/i.exec(line))) rec.tracker = m[1].trim();
      else if ((m = /^Status\s*:\s*(.*)$/i.exec(line))) rec.status = m[1].trim();
      else if ((m = /^Active\s*:\s*(.*)$/i.exec(line))) rec.active = m[1].trim();
      else if ((m = /^Total\s*:\s*(.*)$/i.exec(line))) rec.total = m[1].trim();
      else if ((m = /^Paused\s*:\s*(.*)$/i.exec(line))) rec.paused = m[1].trim();
      else if ((m = /^L\d+\s*:\s*(.*)$/i.exec(line))){
        var parts = m[1].split('|').map(function(p){ return p.trim(); });
        if (parts[0] && !/^name$/i.test(parts[0])) rec.entries.push({ name: parts[0], people: parts[1]||'', icon: parts[2]||'📍', detail: parts[3]||'' });
      }
    });
    if (rec.entries.length || rec.tracker) blocks.push(rec);
  }
  return blocks;
}
async function maybeImportMapsTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_map_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_map_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_map_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_map_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    var trackers = await rpGet('rp_map_trackers', []);
    var meta = await rpGet('rp_map_tracker_meta', null) || { tracker:'', status:'', active:'', total:'' };
    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var blocks = parseTMapBlocks(rpTagText(String(m.content)));
      blocks.forEach(function(b){
        if (b.tracker) meta.tracker = b.tracker;
        if (b.status) meta.status = b.status;
        if (b.active) meta.active = b.active;
        if (b.total) meta.total = b.total;
        var pausedNames = (b.paused||'').split(/[,;]/).map(function(s){ return s.trim().toLowerCase(); }).filter(Boolean);
        b.entries.forEach(function(e){
          var existing = trackers.find(function(x){ return x.name.trim().toLowerCase()===e.name.trim().toLowerCase(); });
          var isPaused = pausedNames.indexOf(e.name.trim().toLowerCase())>-1;
          if (existing){ existing.people=e.people; existing.icon=e.icon; existing.detail=e.detail; existing.paused=isPaused; existing.hidden=false; existing.updatedAt=Date.now(); }
          else { trackers.push({ id: uid(), name:e.name, people:e.people, icon:e.icon, detail:e.detail, paused:isPaused, hidden:false, updatedAt:Date.now() }); }
        });
        touched = true;
      });
    }
    if (touched){
      await rpSet('rp_map_trackers', trackers);
      await rpSet('rp_map_tracker_meta', meta);
      if (panelOpen && currentScreen === 'maps'){
        var scope = $('.rp_map_scope');
        if (scope) await renderMapsBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Карты', 'Обновление геометок');
      }
    }
  }catch(e){ console.error('RP maps tag import failed', e); }
}

var CONSTELLATION_NAMES = ['Созвездие Лисицы','Созвездие Тишины','Созвездие Долгой Дороги','Созвездие Утреннего Чая','Созвездие Секрета','Созвездие Нежности','Созвездие Второго Шанса','Созвездие Тёплого Пледа','Созвездие Случайной Встречи','Созвездие Бессонной Ночи','Созвездие Домашнего Света','Созвездие Старого Письма'];
var gameDots = [];
var gameState = null;
function generateGameDots(n){
  var dots = [];
  var attempts = 0;
  while (dots.length < n && attempts < 500){
    attempts++;
    var x = 12 + Math.random()*76, y = 12 + Math.random()*76;
    var ok = dots.every(function(d){ return Math.hypot(d.x-x, d.y-y) > 16; });
    if (ok) dots.push({ x:x, y:y });
  }
  return dots;
}
function openConstellationGame(){
  gameDots = generateGameDots(6 + Math.floor(Math.random()*2));
  gameState = { path:[], nextIndex:0, drawing:false };
  var backdrop = el('div','rp_map_game_backdrop');
  backdrop.id = 'rp_map_game_backdrop';
  backdrop.innerHTML = '<div style="position:relative;">'+
    '<div class="rp_map_game_close" id="rp_map_game_close"><svg width="13" height="13"><use href="#rpi-x"/></svg></div>'+
    '<div class="rp_map_game_title">✨ Созвездие</div>'+
    '<div class="rp_map_game_sub">Проведи одну линию через все точки по порядку — от 1 до '+gameDots.length+'</div>'+
    '<div class="rp_map_game_canvas" id="rp_map_game_canvas">'+
      '<svg class="rp_map_route_line" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline id="rp_map_game_poly" points="" fill="none" stroke="#5eead4" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'+
      gameDots.map(function(d,i){ return '<div class="rp_map_game_dot" data-i="'+i+'" style="left:'+d.x+'%;top:'+d.y+'%;">'+(i+1)+'</div>'; }).join('')+
    '</div>'+
    '<div class="rp_map_game_actions"><div class="rp_map_game_btn" id="rp_map_game_restart">Новые точки</div></div>'+
    '<div class="rp_map_gallery" id="rp_map_gallery"></div>'+
  '</div>';
  $('#rp_screen').appendChild(backdrop);
  $('#rp_map_game_close', backdrop).addEventListener('click', function(){ backdrop.remove(); });
  $('#rp_map_game_restart', backdrop).addEventListener('click', function(){ backdrop.remove(); openConstellationGame(); });
  renderConstellationGallery(backdrop);
  wireConstellationCanvas($('#rp_map_game_canvas', backdrop));
}
function wireConstellationCanvas(canvasEl){
  var poly = $('#rp_map_game_poly', canvasEl);
  function pct(e){
    var rect = canvasEl.getBoundingClientRect();
    return { x: Math.max(0,Math.min(100,(e.clientX-rect.left)/rect.width*100)), y: Math.max(0,Math.min(100,(e.clientY-rect.top)/rect.height*100)) };
  }
  function updateDotClasses(){
    canvasEl.querySelectorAll('.rp_map_game_dot').forEach(function(d){
      var i = parseInt(d.getAttribute('data-i'),10);
      d.classList.toggle('done', i < gameState.nextIndex);
    });
  }
  function resetStroke(startP){
    gameState.path = startP ? [startP] : [];
    gameState.nextIndex = 0;
    gameState.drawing = true;
    updateDotClasses();
    poly.setAttribute('points', gameState.path.map(function(p){ return p.x+','+p.y; }).join(' '));
  }
  canvasEl.addEventListener('pointerdown', function(e){
    canvasEl.setPointerCapture(e.pointerId);
    resetStroke(pct(e));
  });
  canvasEl.addEventListener('pointermove', function(e){
    if (!gameState.drawing) return;
    var p = pct(e);
    gameState.path.push(p);
    poly.setAttribute('points', gameState.path.map(function(pt){ return pt.x+','+pt.y; }).join(' '));
    if (gameState.nextIndex < gameDots.length){
      var target = gameDots[gameState.nextIndex];
      if (Math.hypot(target.x-p.x, target.y-p.y) < 9){
        gameState.nextIndex++;
        updateDotClasses();
      }
    }
  });
  function finish(){
    if (!gameState.drawing) return;
    gameState.drawing = false;
    if (gameState.nextIndex >= gameDots.length) onConstellationSuccess(canvasEl.closest('.rp_map_game_backdrop'));
    else toast('Не хватило точек — потяни линию заново');
  }
  canvasEl.addEventListener('pointerup', finish);
  canvasEl.addEventListener('pointercancel', finish);
}
async function onConstellationSuccess(backdrop){
  var name = CONSTELLATION_NAMES[Math.floor(Math.random()*CONSTELLATION_NAMES.length)];
  var list = await rpGet('rp_constellations', []);
  list.unshift({ id: uid(), name: name, dots: gameDots, createdAt: Date.now(), hidden:false });
  await rpSet('rp_constellations', list.slice(0,40));
  toast('Готово! Это «'+name+'»');
  if (backdrop) renderConstellationGallery(backdrop);
}
function constellationThumbSvg(dots){
  var pts = dots.map(function(d){ return d.x+','+d.y; }).join(' ');
  var circles = dots.map(function(d){ return '<circle cx="'+d.x+'" cy="'+d.y+'" r="3" fill="#fef08a"/>'; }).join('');
  return '<svg viewBox="0 0 100 100" width="100%" height="100%"><polyline points="'+pts+'" fill="none" stroke="#5eead4" stroke-width="2"/>'+circles+'</svg>';
}
async function renderConstellationGallery(backdrop){
  var wrap = $('#rp_map_gallery', backdrop);
  if (!wrap) return;
  var list = (await rpGet('rp_constellations', [])).filter(function(c){ return !c.hidden; });
  if (!list.length){ wrap.innerHTML = ''; return; }
  wrap.innerHTML = list.slice(0,12).map(function(c){
    return '<div class="rp_map_gallery_item" data-id="'+c.id+'"><div class="rp_map_gallery_thumb">'+constellationThumbSvg(c.dots)+'</div><div class="rp_map_gallery_name">'+escapeHtml(c.name)+'</div></div>';
  }).join('');
  rpWireLongPressDelete(wrap, '.rp_map_gallery_item', async function(id){
    var fresh = await rpGet('rp_constellations', []);
    await rpSet('rp_constellations', fresh.filter(function(x){ return x.id!==id; }));
    renderConstellationGallery(backdrop);
  });
}

var SMART_HOME_FIELDS = [
  { key:'temp', label:'Температура', icon:'rpi-therm', color:'#3b82f6' },
  { key:'humidity', label:'Влажность', icon:'rpi-drop', color:'#8b5cf6' },
  { key:'light', label:'Освещение', icon:'rpi-bulb', color:'#f59e0b' },
  { key:'waterHeater', label:'Водонагреватель', icon:'rpi-drop', color:'#06b6d4' },
  { key:'floorHeating', label:'Тёплый пол', icon:'rpi-flame', color:'#f97316' },
  { key:'ventilation', label:'Вентиляция', icon:'rpi-fan', color:'#10b981' }
];
function smartHomeIsOn(status){ return /актив|вкл|on\b/i.test(String(status||'')); }
var SMART_HOME_CLIMATE_MODES = [
  { id:'heat', label:'Обогрев' }, { id:'cool', label:'Охлаждение' }, { id:'eco', label:'Эко' }, { id:'auto', label:'Авто' }
];
var SMART_HOME_COLORS = ['#3b82f6','#8b5cf6','#10b981','#f43f5e','#f59e0b'];
var SMART_HOME_DEVICE_DEFS = [
  { key:'curtain', label:'Шторы', iconOn:'🪟' }, { key:'vacuum', label:'Пылесос', iconOn:'🤖' },
  { key:'tv', label:'Smart TV', iconOn:'📺' }, { key:'audio', label:'Акустика', iconOn:'🎵' },
  { key:'lock', label:'Замок', iconOn:'🔒' }, { key:'plug', label:'Розетка', iconOn:'🔌' }
];
var SMART_HOME_SCENES = [
  { id:'home', emoji:'🙋', label:'Я дома' }, { id:'away', emoji:'🔒', label:'Ушёл из дома' },
  { id:'night', emoji:'🌙', label:'Ночной режим' }, { id:'movie', emoji:'🎬', label:'Киносеанс' },
  { id:'romance', emoji:'💞', label:'Романтика' }
];
var smartHomeRoomFilter = 'all';
SCREENS.smarthome = {
  title: 'Умный дом',
  async render(container){
    container.innerHTML = '';
    container.style.padding = '0';
    smartHomeRoomFilter = 'all';
    var scope = el('div','rp_sh_scope');
    container.appendChild(scope);
    await buildSmartHomeMenu(scope);
    await renderSmartHomeBody(scope);
  }
};
function smartHomeRoomDefaults(){
  return { climateMode:'auto', brightness:70, color:'#3b82f6', devices:{ curtain:false, vacuum:false, tv:false, audio:false, lock:true, plug:false }, climateExtra:null };
}
async function generateClimateExtra(room){
  try{
    var card = await getCharCard();
    var prompt = 'Придумай короткие технические показатели климат-контроля для комнаты «'+room.name+'» умного дома в этой истории (качество воздуха, скорость вентилятора, состояние фильтра).'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nОтветь СТРОГО построчно без пояснений:\nAir: <качество воздуха, короткое, напр. "AQI 12, отличное">\nFan: <скорость, напр. "Авто" или "Средняя">\nFilter: <состояние фильтра, напр. "Ресурс 88%">';
    var raw = await callModel(prompt);
    var text = String(raw||''); var out = {}; var m;
    if ((m = /Air\s*:\s*(.+)/i.exec(text))) out.air = m[1].trim().slice(0,60);
    if ((m = /Fan\s*:\s*(.+)/i.exec(text))) out.fan = m[1].trim().slice(0,40);
    if ((m = /Filter\s*:\s*(.+)/i.exec(text))) out.filter = m[1].trim().slice(0,40);
    return Object.keys(out).length ? out : null;
  }catch(e){ console.error('RP generateClimateExtra failed', e); return null; }
}
async function generateSceneFlavor(sceneLabel){
  try{
    var card = await getCharCard();
    var prompt = 'Опиши одним коротким атмосферным предложением, что происходит в доме, когда срабатывает сценарий умного дома «'+sceneLabel+'».'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nБез списков и пояснений, только само предложение.';
    var raw = await callModel(prompt);
    return String(raw||'').trim().split('\n')[0].slice(0,180);
  }catch(e){ console.error('RP generateSceneFlavor failed', e); return ''; }
}
async function generateSecurityStatus(cameraName){
  try{
    var card = await getCharCard();
    var prompt = 'Для умного дома в этой истории придумай короткое описание картинки с камеры «'+(cameraName||'Входная дверь')+'" (1 атмосферное предложение) и статус трёх датчиков безопасности: движение, протечка воды, дым/CO.'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nОтветь СТРОГО построчно без пояснений:\nCam: <описание картинки с камеры>\nMotion: <статус датчика движения>\nLeak: <статус датчика протечки>\nSmoke: <статус датчика дыма>';
    var raw = await callModel(prompt);
    var text = String(raw||''); var out = {}; var m;
    if ((m = /Cam\s*:\s*(.+)/i.exec(text))) out.camDesc = m[1].trim().slice(0,160);
    if ((m = /Motion\s*:\s*(.+)/i.exec(text))) out.motion = m[1].trim().slice(0,60);
    if ((m = /Leak\s*:\s*(.+)/i.exec(text))) out.leak = m[1].trim().slice(0,60);
    if ((m = /Smoke\s*:\s*(.+)/i.exec(text))) out.smoke = m[1].trim().slice(0,60);
    return Object.keys(out).length ? out : null;
  }catch(e){ console.error('RP generateSecurityStatus failed', e); return null; }
}
async function generateEnergyForecast(){
  try{
    var card = await getCharCard();
    var prompt = 'Придумай одну короткую фразу-прогноз расхода электроэнергии умного дома на месяц в этой истории (с примерной суммой в рублях), в разговорном стиле.'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\nБез списков и пояснений, только сама фраза.';
    var raw = await callModel(prompt);
    return String(raw||'').trim().split('\n')[0].slice(0,140);
  }catch(e){ console.error('RP generateEnergyForecast failed', e); return ''; }
}
async function buildSmartHomeMenu(scope){
  $('#rp_appbar_menu_btn').style.display = 'flex';
  var menu = buildAppbarMenu();
  menu.innerHTML =
    '<div class="rp_btn rp_sm" id="rp_sh_menu_lore"><svg><use href="#rpi-note"/></svg><span>Саммари в лорбук</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_sh_menu_hide"><svg><use href="#rpi-eyeoff"/></svg><span>Хайд</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_sh_menu_unhide"><svg><use href="#rpi-eye"/></svg><span>Анхайд</span></div>';
  menu.appendChild(buildOocButton('ooc-smarthome', gatherOocSmartHome));

  wireBusyButton($('#rp_sh_menu_lore', menu), 'sh-lore', async function(){
    var parts = await gatherOocSmartHome();
    if (!parts.length){ toast('Пока нет данных'); closeAppbarMenu(); return; }
    await upsertLorebookEntry('rp-smarthome', 'Умный дом', parts.join('\n\n'));
    toast('Сохранено в лорбук');
    closeAppbarMenu();
  });
  wireBusyButton($('#rp_sh_menu_hide', menu), 'sh-hide', async function(){
    var changed = await hideSmartHomeList();
    toast(changed ? 'Скрыто (кроме последней комнаты)' : 'Нечего скрывать');
    closeAppbarMenu();
    await renderSmartHomeBody(scope);
  });
  wireBusyButton($('#rp_sh_menu_unhide', menu), 'sh-unhide', async function(){
    var changed = await unhideSmartHomeList();
    toast(changed ? 'Показано всё скрытое' : 'Нечего показывать');
    closeAppbarMenu();
    await renderSmartHomeBody(scope);
  });
}
async function renderSmartHomeBody(scope){
  scope.innerHTML = '';
  var allRooms = await rpGet('rp_smarthome_rooms', []);
  var rooms = allRooms.filter(function(r){ return !r.hidden; });
  var touchedDefaults = false;
  rooms.forEach(function(r){
    var defs = smartHomeRoomDefaults();
    Object.keys(defs).forEach(function(k){ if (r[k]===undefined){ r[k] = defs[k]; touchedDefaults = true; } });
  });
  if (touchedDefaults) await rpSet('rp_smarthome_rooms', allRooms);

  var temps = rooms.map(function(r){ var n = parseFloat(String(r.temp||'').replace(',','.')); return isNaN(n)?null:n; }).filter(function(n){ return n!==null; });
  var avgTemp = temps.length ? (temps.reduce(function(a,b){ return a+b; },0)/temps.length).toFixed(1) : null;
  var hums = rooms.map(function(r){ var n = parseFloat(String(r.humidity||'').replace(',','.')); return isNaN(n)?null:n; }).filter(function(n){ return n!==null; });
  var avgHum = hums.length ? Math.round(hums.reduce(function(a,b){ return a+b; },0)/hums.length) : null;
  var activeRooms = rooms.filter(function(r){ return smartHomeIsOn(r.status); }).length;
  var activeDevices = rooms.reduce(function(acc,r){ return acc + Object.keys(r.devices||{}).filter(function(k){ return r.devices[k]; }).length; }, 0);
  var topGrid = el('div','rp_sh_top_grid');
  topGrid.innerHTML =
    '<div class="rp_sh_metric_card"><div class="rp_sh_metric_label">Температура в доме</div><div class="rp_sh_metric_val">'+(avgTemp!==null?avgTemp+'°C':'—')+'</div></div>'+
    '<div class="rp_sh_metric_card"><div class="rp_sh_metric_label">Влажность</div><div class="rp_sh_metric_val">'+(avgHum!==null?avgHum+'%':'—')+'</div></div>'+
    '<div class="rp_sh_metric_card"><div class="rp_sh_metric_label">Активные комнаты</div><div class="rp_sh_metric_val">'+activeRooms+' / '+rooms.length+'</div></div>'+
    '<div class="rp_sh_metric_card"><div class="rp_sh_metric_label">Включённые приборы</div><div class="rp_sh_metric_val">'+activeDevices+'</div></div>';
  scope.appendChild(topGrid);

  var sceneState = await rpGet('rp_smarthome_scene', null);
  var sceneRow = el('div','rp_sh_scene_row');
  sceneRow.innerHTML = SMART_HOME_SCENES.map(function(s){
    return '<div class="rp_sh_scene_btn'+(sceneState && sceneState.id===s.id?' on':'')+'" data-scene="'+s.id+'"><span class="rp_sh_scene_emoji">'+s.emoji+'</span>'+s.label+'</div>';
  }).join('');
  scope.appendChild(sceneRow);
  if (sceneState && sceneState.banner){
    var banner = el('div','rp_sh_scene_banner');
    banner.textContent = '✨ '+sceneState.banner;
    scope.appendChild(banner);
  }
  sceneRow.querySelectorAll('.rp_sh_scene_btn').forEach(function(btn){
    btn.addEventListener('click', async function(){
      var sceneId = btn.getAttribute('data-scene');
      var scene = SMART_HOME_SCENES.find(function(s){ return s.id===sceneId; });
      btn.style.opacity = '.55';
      var fresh = await rpGet('rp_smarthome_rooms', []);
      fresh.forEach(function(r){
        if (!r.devices) r.devices = smartHomeRoomDefaults().devices;
        if (sceneId==='home'){ r.climateMode='auto'; r.brightness=80; }
        else if (sceneId==='away'){ r.climateMode='eco'; r.brightness=0; r.devices.lock=true; }
        else if (sceneId==='night'){ r.climateMode='eco'; r.brightness=5; }
        else if (sceneId==='movie'){ r.brightness=15; r.devices.tv=true; }
        else if (sceneId==='romance'){ r.brightness=25; r.color='#f43f5e'; r.devices.audio=true; }
      });
      await rpSet('rp_smarthome_rooms', fresh);
      var flavor = await generateSceneFlavor(scene.label);
      await rpSet('rp_smarthome_scene', { id:sceneId, banner: flavor || ('Сценарий «'+scene.label+'» запущен.') });
      toast('Сценарий «'+scene.label+'» запущен');
      await renderSmartHomeBody(scope);
    });
  });

  if (rooms.length){
    var tabs = el('div','rp_sh_roomtabs');
    tabs.innerHTML = '<div class="rp_sh_roomtab'+(smartHomeRoomFilter==='all'?' on':'')+'" data-room="all">Все комнаты</div>'+
      rooms.map(function(r){ return '<div class="rp_sh_roomtab'+(smartHomeRoomFilter===r.id?' on':'')+'" data-room="'+r.id+'">'+escapeHtml(r.name)+'</div>'; }).join('');
    scope.appendChild(tabs);
    tabs.querySelectorAll('.rp_sh_roomtab').forEach(function(t){
      t.addEventListener('click', function(){ smartHomeRoomFilter = t.getAttribute('data-room'); renderSmartHomeBody(scope); });
    });
  }

  var visibleRooms = rooms.filter(function(r){ return smartHomeRoomFilter==='all' || smartHomeRoomFilter===r.id; });

  if (!rooms.length){
    var empty = el('div','rp_sh_room_card');
    empty.innerHTML = '<div class="rp_sh_empty">Пока нет подключённых комнат. Они появятся сами по ходу истории, или добавь первую вручную.</div>';
    scope.appendChild(empty);
  } else {
    visibleRooms.forEach(function(r){
      var on = smartHomeIsOn(r.status);
      var card = el('div','rp_sh_room_card');
      card.setAttribute('data-id', r.id);
      var climateExtraHtml = '';
      if (r.climateExtra){
        climateExtraHtml = '<div class="rp_sh_genline">'+
          (r.climateExtra.air?'🌬️ '+escapeHtml(r.climateExtra.air)+'<br>':'')+
          (r.climateExtra.fan?'🔄 Вентилятор: '+escapeHtml(r.climateExtra.fan)+'<br>':'')+
          (r.climateExtra.filter?'🧽 Фильтр: '+escapeHtml(r.climateExtra.filter):'')+
        '</div>';
      }
      card.innerHTML = '<div class="rp_sh_room_head"><div class="rp_sh_room_name"><svg width="15" height="15"><use href="#rpi-house"/></svg>'+escapeHtml(r.name)+'</div><div class="rp_sh_room_badge'+(on?'':' off')+'">'+escapeHtml(r.status||(on?'Активна':'Отключена'))+'</div></div>'+
        '<div class="rp_sh_grid">'+SMART_HOME_FIELDS.map(function(f){
          var v = r[f.key];
          if (!v) return '';
          return '<div class="rp_sh_stat'+(String(v).length > 16 ? ' wide' : '')+'"><div class="rp_sh_stat_icon" style="background:'+f.color+'26;color:'+f.color+';"><svg width="15" height="15"><use href="#'+f.icon+'"/></svg></div><div class="rp_sh_stat_body"><div class="rp_sh_stat_label">'+f.label+'</div><div class="rp_sh_stat_val">'+escapeHtml(v)+'</div></div></div>';
        }).join('')+'</div>'+
        '<div class="rp_sh_subtitle">Режим климата</div>'+
        '<div class="rp_sh_mode_row">'+SMART_HOME_CLIMATE_MODES.map(function(m){ return '<div class="rp_sh_mode_btn'+(r.climateMode===m.id?' on':'')+'" data-mode="'+m.id+'">'+m.label+'</div>'; }).join('')+'</div>'+
        climateExtraHtml+
        '<div class="rp_sh_gen_btn" id="rp_sh_climate_gen_'+r.id+'">✨ Сгенерировать климат-детали</div>'+
        '<div class="rp_sh_subtitle">Освещение</div>'+
        '<div class="rp_sh_slider_row"><div class="rp_sh_slider_head"><span>Яркость</span><span>'+r.brightness+'%</span></div><input type="range" min="0" max="100" value="'+r.brightness+'" data-room="'+r.id+'" class="rp_sh_brightness_slider"></div>'+
        '<div class="rp_sh_color_row">'+SMART_HOME_COLORS.map(function(c){ return '<div class="rp_sh_color_dot'+(r.color===c?' on':'')+'" style="background:'+c+';" data-color="'+c+'"></div>'; }).join('')+'</div>'+
        '<div class="rp_sh_subtitle">Устройства</div>'+
        '<div class="rp_sh_devices_grid">'+SMART_HOME_DEVICE_DEFS.map(function(d){
          var isOn = !!(r.devices && r.devices[d.key]);
          return '<div class="rp_sh_device_chip"><span>'+d.iconOn+' '+d.label+'</span><div class="rp_sh_device_toggle'+(isOn?' on':'')+'" data-device="'+d.key+'"></div></div>';
        }).join('')+'</div>'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>';
      scope.appendChild(card);

      card.querySelectorAll('.rp_sh_mode_btn').forEach(function(mb){
        mb.addEventListener('click', async function(){
          var fresh = await rpGet('rp_smarthome_rooms', []);
          var fr = fresh.find(function(x){ return x.id===r.id; });
          if (fr){ fr.climateMode = mb.getAttribute('data-mode'); await rpSet('rp_smarthome_rooms', fresh); }
          await renderSmartHomeBody(scope);
        });
      });
      $('.rp_sh_brightness_slider', card).addEventListener('change', async function(e){
        var fresh = await rpGet('rp_smarthome_rooms', []);
        var fr = fresh.find(function(x){ return x.id===r.id; });
        if (fr){ fr.brightness = parseInt(e.target.value,10); await rpSet('rp_smarthome_rooms', fresh); }
      });
      card.querySelectorAll('.rp_sh_color_dot').forEach(function(cd){
        cd.addEventListener('click', async function(){
          var fresh = await rpGet('rp_smarthome_rooms', []);
          var fr = fresh.find(function(x){ return x.id===r.id; });
          if (fr){ fr.color = cd.getAttribute('data-color'); await rpSet('rp_smarthome_rooms', fresh); }
          await renderSmartHomeBody(scope);
        });
      });
      card.querySelectorAll('.rp_sh_device_toggle').forEach(function(dt){
        dt.addEventListener('click', async function(){
          var fresh = await rpGet('rp_smarthome_rooms', []);
          var fr = fresh.find(function(x){ return x.id===r.id; });
          if (fr){ if (!fr.devices) fr.devices = smartHomeRoomDefaults().devices; var dk = dt.getAttribute('data-device'); fr.devices[dk] = !fr.devices[dk]; await rpSet('rp_smarthome_rooms', fresh); }
          await renderSmartHomeBody(scope);
        });
      });
      wireBusyButton($('#rp_sh_climate_gen_'+r.id, card), 'sh-climate-'+r.id, async function(){
        var extra = await generateClimateExtra(r);
        if (extra){
          var fresh = await rpGet('rp_smarthome_rooms', []);
          var fr = fresh.find(function(x){ return x.id===r.id; });
          if (fr){ fr.climateExtra = extra; await rpSet('rp_smarthome_rooms', fresh); }
        }
        await renderSmartHomeBody(scope);
      });
    });
    rpWireLongPressDelete(scope, '.rp_sh_room_card[data-id]', async function(id){
      var list = await rpGet('rp_smarthome_rooms', []);
      await rpSet('rp_smarthome_rooms', list.filter(function(x){ return x.id!==id; }));
      await renderSmartHomeBody(scope);
    });
  }

  var formCard = el('div','rp_sh_form_card');
  formCard.innerHTML = '<input class="rp_input" type="text" id="rp_sh_new_room" placeholder="Название комнаты...">'+
    '<div class="rp_sh_form_row">'+
      '<input class="rp_input" type="text" id="rp_sh_new_temp" placeholder="Температура">'+
      '<input class="rp_input" type="text" id="rp_sh_new_humidity" placeholder="Влажность">'+
      '<input class="rp_input" type="text" id="rp_sh_new_light" placeholder="Освещение">'+
      '<input class="rp_input" type="text" id="rp_sh_new_vent" placeholder="Вентиляция">'+
    '</div>'+
    '<div class="rp_sh_btn" id="rp_sh_add_room"><svg width="13" height="13"><use href="#rpi-plus"/></svg><span>Добавить комнату</span></div>';
  scope.appendChild(formCard);
  $('#rp_sh_add_room', formCard).addEventListener('click', async function(){
    var name = $('#rp_sh_new_room', formCard).value.trim();
    if (!name){ toast('Введи название комнаты'); return; }
    var list = await rpGet('rp_smarthome_rooms', []);
    list.push(Object.assign({
      id: uid(), name: name.slice(0,40), status:'Активна',
      temp: $('#rp_sh_new_temp', formCard).value.trim().slice(0,30),
      humidity: $('#rp_sh_new_humidity', formCard).value.trim().slice(0,30),
      light: $('#rp_sh_new_light', formCard).value.trim().slice(0,30),
      waterHeater:'', floorHeating:'',
      ventilation: $('#rp_sh_new_vent', formCard).value.trim().slice(0,30),
      hidden:false, updatedAt: Date.now(), source:'manual'
    }, smartHomeRoomDefaults()));
    await rpSet('rp_smarthome_rooms', list);
    toast('Комната добавлена');
    await renderSmartHomeBody(scope);
  });

  var security = await rpGet('rp_smarthome_security', null) || { activeCam: (rooms[0]||{}).id || null, camDesc:'', motion:'', leak:'', smoke:'' };
  var secSection = el('div','rp_sh_section');
  var camRoom = rooms.find(function(r){ return r.id===security.activeCam; });
  secSection.innerHTML = '<div class="rp_sh_section_title"><svg width="17" height="17"><use href="#rpi-shield"/></svg>Видеонаблюдение и датчики</div>'+
    '<div class="rp_sh_cam_box"><div class="rp_sh_cam_tag"><svg width="11" height="11"><use href="#rpi-camera"/></svg> '+escapeHtml(camRoom?camRoom.name:'Камера')+'</div></div>'+
    (security.camDesc ? '<div class="rp_sh_genline" style="margin-top:-4px;margin-bottom:10px;">'+escapeHtml(security.camDesc)+'</div>' : '')+
    (rooms.length ? '<div class="rp_sh_cam_row">'+rooms.map(function(r){ return '<div class="rp_sh_cam_btn'+(security.activeCam===r.id?' on':'')+'" data-cam="'+r.id+'">'+escapeHtml(r.name)+'</div>'; }).join('')+'</div>' : '')+
    '<div class="rp_sh_subtitle">Датчики безопасности</div>'+
    '<div class="rp_sh_sensor_row"><span>Движение</span><span>'+(security.motion?escapeHtml(security.motion):'—')+'</span></div>'+
    '<div class="rp_sh_sensor_row"><span>Протечка воды</span><span>'+(security.leak?escapeHtml(security.leak):'—')+'</span></div>'+
    '<div class="rp_sh_sensor_row"><span>Дым и CO</span><span>'+(security.smoke?escapeHtml(security.smoke):'—')+'</span></div>'+
    '<div class="rp_sh_gen_btn" id="rp_sh_security_gen">✨ Сгенерировать картинку и датчики</div>';
  scope.appendChild(secSection);
  secSection.querySelectorAll('.rp_sh_cam_btn').forEach(function(cb){
    cb.addEventListener('click', async function(){
      var fresh = await rpGet('rp_smarthome_security', null) || {};
      fresh.activeCam = cb.getAttribute('data-cam');
      await rpSet('rp_smarthome_security', fresh);
      await renderSmartHomeBody(scope);
    });
  });
  wireBusyButton($('#rp_sh_security_gen', secSection), 'sh-security-gen', async function(){
    var fresh = await rpGet('rp_smarthome_security', null) || {};
    var camR = rooms.find(function(r){ return r.id===fresh.activeCam; });
    var status = await generateSecurityStatus(camR?camR.name:'Входная дверь');
    if (status) Object.assign(fresh, status);
    await rpSet('rp_smarthome_security', fresh);
    await renderSmartHomeBody(scope);
  });

  var energy = await rpGet('rp_smarthome_energy', null) || { forecast:'' };
  var dow = ['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
  var seed = rooms.length + 3;
  var weekly = dow.map(function(_,i){ return 2.5 + Math.abs(Math.sin(seed+i*1.3))*4; });
  var maxW = Math.max.apply(null, weekly);
  var enSection = el('div','rp_sh_section');
  enSection.innerHTML = '<div class="rp_sh_section_title"><svg width="17" height="17"><use href="#rpi-therm"/></svg>Энергетика</div>'+
    '<div class="rp_sh_chart_row">'+weekly.map(function(v){ return '<div class="rp_sh_chart_bar" style="height:'+Math.max(6,Math.round(v/maxW*100))+'%;"></div>'; }).join('')+'</div>'+
    '<div class="rp_sh_chart_labels">'+dow.map(function(d){ return '<span>'+d+'</span>'; }).join('')+'</div>'+
    (energy.forecast ? '<div class="rp_sh_genline">'+escapeHtml(energy.forecast)+'</div>' : '')+
    '<div class="rp_sh_gen_btn" id="rp_sh_energy_gen">✨ Сгенерировать прогноз</div>';
  scope.appendChild(enSection);
  wireBusyButton($('#rp_sh_energy_gen', enSection), 'sh-energy-gen', async function(){
    var forecast = await generateEnergyForecast();
    await rpSet('rp_smarthome_energy', { forecast: forecast || energy.forecast });
    await renderSmartHomeBody(scope);
  });
}
function parseSmartHomeBlocks(text){
  var blocks = [];
  var re = /\[SMART_HOME\]([\s\S]*?)\[\/SMART_HOME\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var rec = { room:'', status:'', temp:'', humidity:'', light:'', waterHeater:'', floorHeating:'', ventilation:'' };
    lines.forEach(function(line){
      var m;
      if ((m = /^room\s*:\s*(.*)$/i.exec(line))) rec.room = m[1].trim();
      else if ((m = /^status\s*:\s*(.*)$/i.exec(line))) rec.status = m[1].trim();
      else if ((m = /^temp\s*:\s*(.*)$/i.exec(line))) rec.temp = m[1].trim();
      else if ((m = /^humidity\s*:\s*(.*)$/i.exec(line))) rec.humidity = m[1].trim();
      else if ((m = /^light\s*:\s*(.*)$/i.exec(line))) rec.light = m[1].trim();
      else if ((m = /^water_heater\s*:\s*(.*)$/i.exec(line))) rec.waterHeater = m[1].trim();
      else if ((m = /^floor_heating\s*:\s*(.*)$/i.exec(line))) rec.floorHeating = m[1].trim();
      else if ((m = /^ventilation\s*:\s*(.*)$/i.exec(line))) rec.ventilation = m[1].trim();
    });
    if (rec.room) blocks.push(rec);
  }
  return blocks;
}
async function maybeImportSmartHomeTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_smarthome_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_smarthome_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_smarthome_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_smarthome_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    var rooms = await rpGet('rp_smarthome_rooms', []);
    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var blocks = parseSmartHomeBlocks(rpTagText(String(m.content)));
      blocks.forEach(function(b){
        var existing = rooms.find(function(x){ return x.name.trim().toLowerCase()===b.room.trim().toLowerCase(); });
        var data = { status:b.status, temp:b.temp, humidity:b.humidity, light:b.light, waterHeater:b.waterHeater, floorHeating:b.floorHeating, ventilation:b.ventilation };
        if (existing){ Object.keys(data).forEach(function(k){ if (data[k]) existing[k] = data[k]; }); existing.hidden=false; existing.updatedAt=Date.now(); }
        else { rooms.push(Object.assign({ id: uid(), name:b.room, hidden:false, updatedAt:Date.now(), source:'bridge' }, data)); }
        touched = true;
      });
    }
    if (touched){
      await rpSet('rp_smarthome_rooms', rooms);
      if (panelOpen && currentScreen === 'smarthome'){
        var scope = $('.rp_sh_scope');
        if (scope) await renderSmartHomeBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Умный дом', 'Обновление в умном доме');
      }
    }
  }catch(e){ console.error('RP smart home tag import failed', e); }
}
async function gatherOocSmartHome(){
  var rooms = (await rpGet('rp_smarthome_rooms', [])).filter(function(r){ return !r.hidden; });
  var parts = [];
  if (rooms.length){
    var lines = rooms.map(function(r){
      var bits = SMART_HOME_FIELDS.map(function(f){ return r[f.key] ? f.label+': '+r[f.key] : null; }).filter(Boolean);
      var devOn = r.devices ? Object.keys(r.devices).filter(function(k){ return r.devices[k]; }) : [];
      var devNames = devOn.map(function(k){ var d = SMART_HOME_DEVICE_DEFS.find(function(x){ return x.key===k; }); return d?d.label:k; });
      return '- '+r.name+' ('+(r.status||'—')+')'+(bits.length?': '+bits.join(', '):'')+(r.climateMode?', режим: '+r.climateMode:'')+(devNames.length?', приборы вкл: '+devNames.join(', '):'');
    });
    parts.push('Умный дом (комнаты):\n'+lines.join('\n'));
  }
  var scene = await rpGet('rp_smarthome_scene', null);
  if (scene && scene.banner) parts.push('Умный дом (сценарий): '+scene.banner);
  return parts;
}
async function hideSmartHomeList(){
  var list = await rpGet('rp_smarthome_rooms', []);
  var changed = false;
  for (var i=0;i<list.length-hk();i++){ if (!list[i].hidden){ list[i].hidden = true; changed = true; } }
  if (changed) await rpSet('rp_smarthome_rooms', list);
  return changed;
}
async function unhideSmartHomeList(){
  var list = await rpGet('rp_smarthome_rooms', []);
  var changed = false;
  list.forEach(function(r){ if (r.hidden){ r.hidden = false; changed = true; } });
  if (changed) await rpSet('rp_smarthome_rooms', list);
  return changed;
}

