function bbRenderShop(scope){
  scope.innerHTML = '';
  bbSubHeader(scope, 'Магазин скинов');
  BB_SKINS.forEach(function(s){
    var owned = bbStats.owned.indexOf(s.id)>-1;
    var row = el('div','rp_bb_glass rp_bb_skin_row');
    row.innerHTML = '<div class="info"><div class="rp_bb_skin_swatch" style="background:linear-gradient(135deg,'+BB_BLOCK_COLORS[1]+','+BB_BLOCK_COLORS[0]+');"></div>'+
      '<div><div class="rp_bb_skin_name">'+s.name+'</div><div class="rp_bb_skin_desc">'+s.desc+'</div></div></div>'+
      (owned ? '<div class="rp_bb_skin_btn '+(bbStats.skin===s.id?'owned':'buy')+'" data-skin="'+s.id+'">'+(bbStats.skin===s.id?'Выбрано':'Выбрать')+'</div>'
             : '<div class="rp_bb_skin_btn buy" data-buy="'+s.id+'">🪙 '+s.cost+'</div>');
    scope.appendChild(row);
    var btn = row.querySelector('[data-skin]') || row.querySelector('[data-buy]');
    btn.addEventListener('click', async function(){
      if (owned){ bbStats.skin = s.id; await bbSaveStats(); bbRenderShop(scope); }
      else {
        if (bbStats.coins < s.cost){ toast('Не хватает монет'); return; }
        bbStats.coins -= s.cost; bbStats.owned.push(s.id); bbStats.skin = s.id;
        await bbSaveStats(); toast('Скин куплен'); bbRenderShop(scope);
      }
    });
  });
}
