function petPalette(sp, v){
  var h = (PET_VARIANTS[v|0] || PET_VARIANTS[0]).h;
  if (!h || sp.id==='panda' || sp.id==='unicorn') return sp.c.slice();
  return [pHue(sp.c[0],h), pHue(sp.c[1],h*0.5), sp.c[2]];
}
