function petFindDecor(id){
  var lists = [PET_WALLS, PET_FLOORS, PET_FURN, PET_RUGS, PET_WINDOWS, PET_ARTS, PET_CEILS], i, f;
  for (i=0;i<lists.length;i++){ f = petFindIn(lists[i], id); if (f) return f; }
  return null;
}
function petApplyPromo(state, code, p){
  var rewards = [];
  if (p.c){ state.coins += p.c; rewards.push({ ico:'coin', t:'+'+p.c.toLocaleString('ru-RU')+' монет', s:'на счёт' }); }
  if (p.g){ state.gems += p.g; rewards.push({ ico:'gem', t:'+'+p.g.toLocaleString('ru-RU')+' кристаллов', s:'на счёт' }); }
  (p.acc || []).forEach(function(id){ var a = petFindIn(PET_ACCS, id); if (!a) return; var had = state.owned[id]; state.owned[id] = 1; rewards.push({ ico:'hanger', t:a.name, s: had ? 'уже было — в гардеробе' : 'новый аксессуар' }); });
  (p.dec || []).forEach(function(id){ var d = petFindDecor(id); if (!d) return; var had = state.owned[id]; state.owned[id] = 1; rewards.push({ ico:'house', t:d.name, s: had ? 'уже было' : 'для комнаты' }); });
  (p.egg || []).forEach(function(t){ var eg = petFindIn(PET_EGGS, t); if (!eg) return; var at = petStoreEgg(state, eg.id); rewards.push({ ico:'gift', t:eg.name, s: at < 0 ? 'в запас' : 'греется в комнате '+(at+1) }); });
  (p.sc || []).forEach(function(id){ var sc = petFindIn(PET_SCENES, id); if (!sc) return; var had = state.ownedScenes.indexOf(id) >= 0; if (!had) state.ownedScenes.push(id); rewards.push({ ico:'house', t:sc.name, s: had ? 'уже было' : 'новый фон' }); });
  Object.keys(p.cons || {}).forEach(function(id){ var it = PET_CONS_ALL[id]; if (!it) return; state.inventory[id] = (state.inventory[id]||0) + p.cons[id]; rewards.push({ ico:it.icon, t:it.name+' ×'+p.cons[id], s:'в запас' }); });
  if (p.ach){ var a2 = PET_ACH_BY[p.ach]; if (a2){ state.ach = state.ach || {}; var had2 = !!state.ach[p.ach]; if (!had2) state.ach[p.ach] = Date.now(); rewards.push({ medal:a2, t:'Достижение: '+a2.name, s: had2 ? 'уже открыто' : a2.desc }); } }
  return rewards;
}
function petOpenPromo(state, scope){
  var sh = thSheet('<div style="font-weight:900;font-size:15px;margin-bottom:4px;">Промокод</div>'+
    '<div class="th_hint" style="margin-bottom:8px;">Введи код — получишь подарок: монеты, кристаллы, аксессуары, вещи для комнаты или достижение.</div>'+
    '<input class="rp_input" id="pt_code_in" maxlength="24" placeholder="КОД" autocapitalize="characters" autocomplete="off" style="text-transform:uppercase;letter-spacing:.08em;text-align:center;font-weight:900;">'+
    '<div class="th_row2" style="margin-top:12px;"><div class="th_btn ghost" id="pt_code_x">Закрыть</div><div class="th_btn" id="pt_code_ok">Активировать</div></div>');
  var inp = $('#pt_code_in', sh); setTimeout(function(){ try{ inp.focus(); }catch(e){} }, 60);
  $('#pt_code_x', sh).addEventListener('click', function(){ sh.remove(); });
  var go = async function(){
    var code = inp.value.toUpperCase().replace(/[^A-Z0-9А-ЯЁ]/g,'');
    if (!code){ toast('Впиши код'); return; }
    var hk = rpH(code), p = PET_PROMOS[hk];
    if (!p){ inp.classList.add('pt_shake'); setTimeout(function(){ inp.classList.remove('pt_shake'); }, 500); toast('Такого кода нет'); return; }
    state.promoUsed = state.promoUsed || {};
    if ((state.promoUsed[hk] || state.promoUsed[code]) && !p.admin){ toast('Этот код уже активирован'); return; }
    var rewards = petApplyPromo(state, code, p);
    state.promoUsed[hk] = Date.now();
    await rpSet('rp_pet_state', state);
    await petAddFeedLog('user', p.admin ? 'активировал(а) служебный код' : 'активировал(а) промокод и получил(а) подарок');
    sh.remove();
    petPlayGiftAnim(rewards, p.admin, function(){ renderPetBody(scope); });
  };
  $('#pt_code_ok', sh).addEventListener('click', go);
  inp.addEventListener('keydown', function(e){ if (e.key === 'Enter') go(); });
}
function petPlayGiftAnim(rewards, admin, done){
  var host = $('#rp_screen');
  var ov = el('div','pt_gov');
  var conf = '', cols = ['#f472b6','#fbbf24','#34d399','#60a5fa','#a78bfa','#fb7185'];
  for (var i=0;i<44;i++){
    conf += '<i style="left:'+(10+Math.random()*80).toFixed(1)+'%;background:'+cols[i%cols.length]+';--dx:'+Math.round(-90+Math.random()*180)+'px;--r:'+Math.round(Math.random()*720)+'deg;animation-delay:'+(1.15+Math.random()*0.5).toFixed(2)+'s;width:'+(6+Math.round(Math.random()*5))+'px;height:'+(9+Math.round(Math.random()*8))+'px"></i>';
  }
  ov.innerHTML = '<div class="pt_gov_in"><div class="pt_gov_glow"></div><div class="pt_gbox" id="pt_gbox">'+
    '<svg viewBox="0 0 120 120" width="150" height="150"><g class="pt_g_body"><rect x="18" y="52" width="84" height="56" rx="8" fill="#f472b6"/><rect x="53" y="52" width="14" height="56" fill="#fde68a"/><rect x="18" y="52" width="84" height="8" fill="#000" opacity=".1"/></g>'+
    '<g class="pt_g_lid"><rect x="12" y="34" width="96" height="22" rx="7" fill="#fb7fb8"/><rect x="53" y="34" width="14" height="22" fill="#fde68a"/><path d="M60 34c-14-18-34-12-24-2 6 4 24 2 24 2zM60 34c14-18 34-12 24-2-6 4-24 2-24 2z" fill="#fde68a" stroke="#f5c76a" stroke-width="2"/></g></svg></div>'+
    '<div class="pt_gconf">'+conf+'</div>'+
    '<div class="pt_gov_t">'+(typeof admin === 'string' ? escapeHtml(admin) : admin ? 'Служебный подарок' : 'Подарок!')+'</div>'+
    '<div class="pt_grew">'+rewards.map(function(r, k){ return '<div class="pt_grow" style="animation-delay:'+(1.5+k*0.28).toFixed(2)+'s">'+(r.medal ? petMedal(r.medal, 38) : '<div class="pt_grow_i">'+petIcon(r.ico, 32)+'</div>')+'<div class="pt_grow_b"><div class="pt_grow_t">'+escapeHtml(r.t)+'</div><div class="pt_grow_s">'+escapeHtml(r.s)+'</div></div></div>'; }).join('')+'</div>'+
    '<div class="pt_big pt_gov_ok" style="animation-delay:'+(1.7+rewards.length*0.28).toFixed(2)+'s" id="pt_gov_ok">Забрать</div></div>';
  host.appendChild(ov);
  setTimeout(function(){ var b = $('#pt_gbox', ov); if (b) b.classList.add('open'); }, 1050);
  $('#pt_gov_ok', ov).addEventListener('click', function(){ ov.remove(); if (done) done(); });
}
async function renderPetBody(scope){
  petClearTimer();
  scope.innerHTML = '';
  var state = await rpGet('rp_pet_state', null);
  if (!state){ state = petDefaultState(); }
  petMigrate(state);
  petApplyDecay(state);
  if (state.timeAuto) state.timeOfDay = petClockTime();
  petDaily(state);
  await rpSet('rp_pet_state', state);

  var top = el('div','rp_pet_topbar');
  var qn = petQuestBadge(state);
  top.innerHTML = '<div class="rp_pet_coins"><span class="pt_pill">'+petIcon('coin',20)+'<b id="pt_coins_n">'+state.coins.toLocaleString()+'</b></span><span class="pt_pill">'+petIcon('gem',20)+'<b id="pt_gems_n">'+state.gems+'</b></span></div>'+
    '<div style="display:flex;gap:8px;"><div class="pt_gift'+(qn?' ready':'')+'" id="pt_quests" data-n="'+(qn||'')+'" title="Задания и награды" style="opacity:1;">'+petIcon('scroll',22)+'</div><div class="pt_gift" id="pt_promo" title="Промокод" style="opacity:1;">'+petIcon('ticket',22)+'</div><div class="pt_gift'+(petGiftReady(state)?' ready':'')+'" id="pt_gift" title="Подарок раз в 4 часа">'+petIcon('gift',22)+'</div></div>';
  scope.appendChild(top);
  $('#pt_quests', top).addEventListener('click', function(){ petQuestsSheet(state, scope); });
  $('#pt_gift', top).addEventListener('click', function(){ petClaimGift(state, scope); });
  $('#pt_promo', top).addEventListener('click', function(){ petOpenPromo(state, scope); });

  var body = el('div','rp_pet_body');
  scope.appendChild(body);
  petGuard(body);
  var navDefs = [{ id:'home', label:'Дом', ic:'house' },{ id:'selector', label:'Питомцы', ic:'paw' },{ id:'shop', label:'Магазин', ic:'bag' },{ id:'games', label:'Игры', ic:'gamepad' },{ id:'partner', label:'Пара', ic:'heart' }];
  var nav = el('div','pt_bottombar');
  nav.innerHTML = navDefs.map(function(n){ return '<div class="pt_nav'+(petActiveTab===n.id?' on':'')+'" data-tab="'+n.id+'">'+petIcon(n.ic,26)+'<span>'+n.label+'</span></div>'; }).join('');
  nav.querySelectorAll('.pt_nav').forEach(function(n){ n.addEventListener('click', function(){ if (petBusy) return; petActiveTab = n.getAttribute('data-tab'); var sc = scope.closest('#rp_screens'); renderPetBody(scope).then(function(){ if (sc) sc.scrollTop = 0; }); }); });
  var navAdded = false;
  if (petActiveTab==='home'){
    if (state.reveal) petRenderReveal(body, state, scope);
    else await petRenderRooms(body, state, scope);
  }
  else if (petActiveTab==='selector') await renderPetSelector(body, state, scope);
  else if (petActiveTab==='shop') await renderPetShop(body, state, scope);
  else if (petActiveTab==='games') await renderPetGames(body, state, scope);
  else if (petActiveTab==='partner') await renderPetPartner(body, state, scope);
  scope.appendChild(nav);
}
async function petRenderEggStage(container, state, scope){
  container.innerHTML = '';
  if (!state.egg) return petRenderEmptyRoom(container, state, scope);
  var egg = petFindIn(PET_EGGS, state.egg.type) || PET_EGGS[0], total = (egg.mins||12)*60000;
  var wrap = el('div','pt_eggscene');
  wrap.innerHTML = '<div class="pt_egg_t">'+egg.name+'</div><div class="pt_eggbig" id="pt_eggbig"></div><div class="pt_egg_timer" id="pt_egg_timer"></div>'+
    '<div class="pt_egg_prog"><div id="pt_egg_fill"></div></div>'+
    '<div class="pt_egg_btns" id="pt_egg_btns"></div>';
  container.appendChild(wrap);
  var draw = function(){
    var left = petEggLeft(state), ready = left <= 0, prog = Math.max(0, Math.min(1, 1 - left/total));
    $('#pt_eggbig', wrap).innerHTML = '<div class="'+(ready?'pt_egg_ready':'pt_egg_wobble')+'">'+petEggSVG(state.egg.type, prog, ready)+'</div>';
    $('#pt_egg_timer', wrap).textContent = ready ? 'Готово! Малыш просится наружу' : 'Осталось '+petFmtTime(left);
    $('#pt_egg_fill', wrap).style.width = Math.round(prog*100)+'%';
    var warmLeft = (state.egg.warmAt||0) + 5*60000 - Date.now();
    $('#pt_egg_btns', wrap).innerHTML = ready
      ? '<div class="pt_big" id="pt_hatch">Вылупить</div>'
      : '<div class="pt_btn2'+(warmLeft>0?' off':'')+'" id="pt_warm">'+petIcon('sun',18)+'<span>'+(warmLeft>0 ? 'Согреть через '+petFmtTime(warmLeft) : 'Согреть −2 мин')+'</span></div>'+
        '<div class="pt_btn2 gem" id="pt_speed">'+petIcon('gem',18)+'<span>Ускорить −10 мин · 1</span></div>'+
        '<div class="pt_btn2 gem" id="pt_now">'+petIcon('gem',18)+'<span>Вылупить сразу · '+Math.max(1, Math.ceil(left/60000/6))+'</span></div>';
    var hb = $('#pt_hatch', wrap); if (hb) hb.addEventListener('click', async function(){ await petHatch(state); await renderPetBody(scope); });
    var wb = $('#pt_warm', wrap); if (wb) wb.addEventListener('click', async function(){
      if ((state.egg.warmAt||0) + 5*60000 > Date.now()) return;
      state.egg.warmAt = Date.now(); state.egg.hatchAt -= 2*60000; await rpSet('rp_pet_state', state); toast('Яйцо стало тёплым'); draw();
    });
    var sb = $('#pt_speed', wrap); if (sb) sb.addEventListener('click', async function(){
      if (state.gems < 1){ toast('Нужен 1 кристалл'); return; }
      state.gems -= 1; state.egg.hatchAt -= 10*60000; await rpSet('rp_pet_state', state); await renderPetBody(scope);
    });
    var nb = $('#pt_now', wrap); if (nb) nb.addEventListener('click', async function(){
      var cost = Math.max(1, Math.ceil(petEggLeft(state)/60000/6));
      if (state.gems < cost){ toast('Нужно кристаллов: '+cost); return; }
      state.gems -= cost; state.egg.hatchAt = Date.now(); await rpSet('rp_pet_state', state); await renderPetBody(scope);
    });
  };
  draw();
  petTimer = setInterval(function(){
    if (!document.body.contains(wrap)){ petClearTimer(); return; }
    if (!panelOpen) return;
    var left = petEggLeft(state);
    if (left <= 0){ petClearTimer(); draw(); return; }
    $('#pt_egg_timer', wrap).textContent = 'Осталось '+petFmtTime(left);
    $('#pt_egg_fill', wrap).style.width = Math.round(Math.max(0, Math.min(1, 1 - left/total))*100)+'%';
    if ((state.egg.warmAt||0) + 5*60000 - Date.now() <= 1000 && $('#pt_warm', wrap) && $('#pt_warm', wrap).classList.contains('off')) draw();
  }, 1000);
}
