    nav.querySelectorAll('[data-slot]').forEach(function(a){ a.addEventListener('click', function(){ var i = +a.getAttribute('data-slot'); petSwitchSlot(state, i, container, scope, i > state.activeSlot ? 1 : -1); }); });
