  state.coins -= fee; rpSet('rp_pet_state', state);
  container.innerHTML = '';
  var head = el('div','rp_pet_toprow');
  head.innerHTML = '<div class="rp_h" id="rp_pet_game_title">'+(gameDef.name||'')+'</div>'+
    '<div style="display:flex;align-items:center;gap:8px;"><span class="rp_muted">Счёт: <b id="rp_pet_game_score" style="color:var(--text);">0</b></span><div class="rp_pet_game_exit" id="rp_pet_game_exit">Выход</div></div>';
