async function petApplyName(scope, container, state, ps, nm, askBot){
  ps.genome.name = nm; ps.nick = nm; ps.nameTalk = null;
  petSpeechText = 'Теперь меня зовут '+nm+'!';
  await rpSet('rp_pet_state', state);
  await petAddFeedLog('user', 'назвал(а) малыша «'+nm+'»');
  var partner = await rpGet('rp_pet_partner', null);
  var id = state.activePetId;
  if (container && container.isConnected) await renderPetHome(container, state, scope);
  if (!askBot || !partner || partner.status !== 'accepted') return;
  toast('Спрашиваем мнение персонажа…');
  var res = await generatePetNameOpinion(nm, (PET_BY_ID[id]||{}).title || 'питомец');
  if (!res) return;
  var st = petMigrate(await rpGet('rp_pet_state', null) || state);
  var pd = petEnsurePetData(st, id);
  if ((pd.genome && pd.genome.name) !== nm) return;
  pd.nameTalk = { name:nm, decision:res.decision, alt:res.alt || '', message:res.message, at:Date.now() };
  await rpSet('rp_pet_state', st);
  var names = await getNames();
  await petAddFeedLog('char', (res.decision === 'DISPUTE' ? 'не согласен(на) с именем «'+nm+'»'+(res.alt ? ', предлагает «'+res.alt+'»' : '') : 'одобрил(а) имя «'+nm+'»')+': «'+res.message+'»');
  var sc = $('.rp_pet_scope');
  if (panelOpen && currentScreen === 'pet' && sc && petActiveTab === 'home') await renderPetBody(sc);
  else { unreadCount++; updateBadge(); pushHomeNotification('Мой малыш', names.charName+' про имя «'+nm+'»: '+res.message); }
}
