    function dateMethodRow(id, title, hint){
      return '<div class="rp_date_row"><div class="rp_title_row">'+
        '<div><div class="rp_h" style="font-size:12px;">'+title+'</div><div class="rp_muted" style="font-size:10px;margin-top:1px;">'+hint+'</div></div>'+
        '<div class="rp_conseq_check" id="'+id+'"></div>'+
      '</div></div>';
    }
    dateBody.innerHTML =
      '<div class="rp_muted" id="rp_date_status" style="margin-bottom:8px;">Сейчас: <b style="color:var(--text);">'+escapeHtml(curStoryDate)+'</b> ('+escapeHtml(curStoryLabel)+')</div>'+
      dateMethodRow('rp_date_check_context', 'Определять по контексту', 'Работает нестабильно, ищет упоминания даты в контексте') +
      dateMethodRow('rp_date_check_hdr', 'Определять по тегу [HDR]', 'Находит дату по шапке из пресета SATURIC, стабильный вариант') +
      '<div class="rp_date_row"><div class="rp_h" style="font-size:12px;margin-bottom:5px;">Ввести дату вручную</div>'+
      '<div style="display:flex;gap:6px;"><input class="rp_input" type="date" id="rp_storydate_input" value="'+escapeHtml(curStoryDate)+'" style="flex:1;">'+
      '<div class="rp_btn rp_sm" id="rp_storydate_save"><span>OK</span></div></div></div>';
    buildAccordion(paneGeneral, 'Дата в истории', dateBody, false, function(){
      function syncChecks(activeId){
        ['rp_date_check_context','rp_date_check_hdr'].forEach(function(id){
          var on = id === activeId;
          var box = $('#'+id, dateBody);
          box.classList.toggle('on', on);
          box.innerHTML = on ? '<svg><use href="#rpi-check"/></svg>' : '';
        });
      }
      (async function initChecks(){
        if (curStoryLabel === 'по анализу контекста') syncChecks('rp_date_check_context');
        else if (curStoryLabel === 'по тегу [HDR]') syncChecks('rp_date_check_hdr');
      })();
      async function refreshStatus(){
        var d = await getStoryDate();
        var l = await getStoryDateSourceLabel();
        $('#rp_date_status', dateBody).innerHTML = 'Сейчас: <b style="color:var(--text);">'+escapeHtml(d)+'</b> ('+escapeHtml(l)+')';
      }
      function setCheckBusy(box, busy){
        box.style.pointerEvents = busy ? 'none' : '';
        if (busy) box.innerHTML = '<svg class="rp_spin" style="width:12px;height:12px;"><use href="#rpi-spinner"/></svg>';
      }
      $('#rp_date_check_context', dateBody).addEventListener('click', async function(){
        var box = $('#rp_date_check_context', dateBody);
        setCheckBusy(box, true);
        var ok = await analyzeStoryDateByContext();
        setCheckBusy(box, false);
        if (ok) syncChecks('rp_date_check_context'); else syncChecks(box.classList.contains('on') ? 'rp_date_check_context' : null);
        await refreshStatus();
      });
      $('#rp_date_check_hdr', dateBody).addEventListener('click', async function(){
        var box = $('#rp_date_check_hdr', dateBody);
        setCheckBusy(box, true);
        var ok = await analyzeStoryDateByHdr();
        setCheckBusy(box, false);
        if (ok) syncChecks('rp_date_check_hdr'); else syncChecks(box.classList.contains('on') ? 'rp_date_check_hdr' : null);
        await refreshStatus();
      });
      $('#rp_storydate_save', dateBody).addEventListener('click', async function(){
        var val = $('#rp_storydate_input', dateBody).value;
        if (!val){ toast('Укажите дату'); return; }
        await setStoryDate(val);
        syncChecks(null);
        toast('Дата истории сохранена');
        await refreshStatus();
      });
    });

    var langBody = el('div');
