var MN_KEY = 'rp_mynotes_v1';
var mnFilter = 'all';
async function mnLoad(){ try{ var v = await PM.store.get(MN_KEY, 'global'); if (Array.isArray(v)) return v; }catch(e){} return []; }
async function mnSave(list){ try{ await PM.store.set(MN_KEY, list, 'global'); return true; }catch(e){ console.error('RP notes save failed', e); toast('Не удалось сохранить заметки'); return false; } }
function mnFmt(ts){ try{ return new Date(ts).toLocaleString('ru-RU', { day:'numeric', month:'short', hour:'2-digit', minute:'2-digit' }); }catch(e){ return ''; } }
SCREENS.mynotes = {
  title: 'Заметки',
  async render(container){
    container.style.flexDirection=''; container.style.height=''; container.style.minHeight='';
    container.style.padding = '10px 14px 16px';
    await mnRenderList(container);
  }
};
async function mnRenderList(container){
  backTarget = openHome;
  container.innerHTML = '';
  var names = await getNames();
  var bot = String(names.charName||'').trim();
  var list = await mnLoad();
  var search = '';
  var top = el('div','rp_mn_top');
  top.innerHTML = '<input class="rp_input" id="rp_mn_search" placeholder="Поиск по заметкам"><div class="rp_btn rp_sm" id="rp_mn_new"><svg style="width:13px;height:13px;"><use href="#rpi-plus"/></svg><span>Новая</span></div>';
  container.appendChild(top);
  var info = el('div','rp_muted','Только для тебя: заметки хранятся на устройстве, бот их не видит и в лорбук они не попадают.');
  info.style.cssText = 'font-size:10px;margin:0 2px 10px;';
  container.appendChild(info);
  var bots = [];
  list.forEach(function(n){ if (n.bot && bots.indexOf(n.bot)===-1) bots.push(n.bot); });
  if (mnFilter !== 'all' && bots.indexOf(mnFilter) === -1) mnFilter = 'all';
  if (bots.length > 1 || (bots.length === 1 && bot && bots[0] !== bot)){
    var chips = el('div','rp_mn_chips');
    chips.innerHTML = '<div class="rp_mn_chip'+(mnFilter==='all'?' on':'')+'" data-f="all">Все</div>'+
      bots.map(function(b){ return '<div class="rp_mn_chip'+(mnFilter===b?' on':'')+'" data-f="'+escapeHtml(b)+'">'+escapeHtml(b)+'</div>'; }).join('');
    container.appendChild(chips);
    chips.querySelectorAll('.rp_mn_chip').forEach(function(c){
      c.addEventListener('click', function(){ mnFilter = c.getAttribute('data-f'); mnRenderList(container); });
    });
  }
  var listWrap = el('div');
  container.appendChild(listWrap);
  function draw(){
    var q = search.trim().toLowerCase();
    var shown = list.filter(function(n){
      if (mnFilter !== 'all' && n.bot !== mnFilter) return false;
      if (!q) return true;
      return (String(n.title||'')+' '+String(n.text||'')).toLowerCase().indexOf(q) !== -1;
    }).sort(function(a,b){ return (b.pinned?1:0)-(a.pinned?1:0) || (b.updated||0)-(a.updated||0); });
    if (!shown.length){
      listWrap.innerHTML = '<div class="rp_empty">'+(list.length ? 'Ничего не найдено.' : 'Пока пусто. Нажми «Новая» и запиши что-нибудь про бота — идеи, факты, планы.')+'</div>';
      return;
    }
    listWrap.innerHTML = shown.map(function(n){
      return '<div class="rp_mn_card" data-id="'+n.id+'"><div class="rp_mn_title">'+(n.pinned?'📌 ':'')+escapeHtml(n.title||'Без названия')+'</div>'+
        (n.text ? '<div class="rp_mn_prev">'+escapeHtml(n.text)+'</div>' : '')+
        '<div class="rp_mn_meta">'+escapeHtml(mnFmt(n.updated||n.created))+(n.bot?' · '+escapeHtml(n.bot):'')+'</div></div>';
    }).join('');
    listWrap.querySelectorAll('.rp_mn_card').forEach(function(c){
      c.addEventListener('click', function(){
        var note = list.find(function(x){ return x.id === c.getAttribute('data-id'); });
        if (note) mnRenderEditor(container, note);
      });
    });
  }
  draw();
  $('#rp_mn_search', top).addEventListener('input', function(e){ search = e.target.value; draw(); });
  $('#rp_mn_new', top).addEventListener('click', async function(){
    var note = { id: uid(), title:'', text:'', bot: bot, pinned:false, created: Date.now(), updated: Date.now(), fresh:true };
    mnRenderEditor(container, note);
  });
}
async function mnRenderEditor(container, note){
  container.innerHTML = '';
  backTarget = function(){ mnLeave(container, note, true); };
  var bar = el('div','rp_mn_bar');
  bar.innerHTML = '<div class="rp_btn rp_ghost rp_xs" id="rp_mn_back"><svg style="width:13px;height:13px;"><use href="#rpi-back"/></svg><span>К заметкам</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_mn_pin"><span>'+(note.pinned?'Открепить':'📌 Закрепить')+'</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_mn_del"><span>Удалить</span></div>'+
    '<span class="rp_mn_saved" id="rp_mn_saved"></span>';
  container.appendChild(bar);
  var t = el('input','rp_input rp_mn_edit_title'); t.placeholder = 'Название'; t.value = note.title||'';
  var x = el('textarea','rp_input rp_mn_edit_text'); x.placeholder = 'Пиши что угодно…'; x.value = note.text||'';
  container.appendChild(t); container.appendChild(x);
  var saved = $('#rp_mn_saved', bar);
  var timer = null;
  async function persist(){
    note.title = t.value; note.text = x.value; note.updated = Date.now();
    var isEmpty = !note.title.trim() && !note.text.trim();
    var list = await mnLoad();
    var idx = list.findIndex(function(n){ return n.id === note.id; });
    if (isEmpty){ if (idx !== -1){ list.splice(idx,1); await mnSave(list); } return; }
    var rec = { id:note.id, title:note.title, text:note.text, bot:note.bot, pinned:!!note.pinned, created:note.created, updated:note.updated };
    if (idx === -1) list.push(rec); else list[idx] = rec;
    if (await mnSave(list)){ saved.textContent = 'Сохранено'; }
  }
  function queue(){ saved.textContent = '…'; clearTimeout(timer); timer = setTimeout(persist, 400); }
  t.addEventListener('input', queue); x.addEventListener('input', queue);
  note._persist = async function(){ clearTimeout(timer); await persist(); };
  $('#rp_mn_back', bar).addEventListener('click', function(){ mnLeave(container, note, true); });
  $('#rp_mn_pin', bar).addEventListener('click', async function(){
    note.pinned = !note.pinned;
    $('#rp_mn_pin', bar).querySelector('span').textContent = note.pinned ? 'Открепить' : '📌 Закрепить';
    await persist();
  });
  $('#rp_mn_del', bar).addEventListener('click', async function(){
    var delBtn = $('#rp_mn_del', bar);
    if (!delBtn.dataset.armed){
      delBtn.dataset.armed = '1'; delBtn.querySelector('span').textContent = 'Точно удалить?';
      setTimeout(function(){ if (delBtn.isConnected){ delete delBtn.dataset.armed; delBtn.querySelector('span').textContent = 'Удалить'; } }, 3000);
      return;
    }
    clearTimeout(timer);
    var list = await mnLoad();
    await mnSave(list.filter(function(n){ return n.id !== note.id; }));
    note._persist = null;
    toast('Заметка удалена');
    mnRenderList(container);
  });
  if (note.fresh){ t.focus(); }
}
async function mnLeave(container, note, rerender){
  if (note._persist){ await note._persist(); note._persist = null; }
  if (rerender) await mnRenderList(container);
}
