    box.querySelectorAll('.sat_chip').forEach(function(ch){ ch.addEventListener('click', function(){ var t = ch.getAttribute('data-t'); var i = badges.indexOf(t); if (i === -1) badges.push(t); else badges.splice(i,1); drawBadges(); }); });
