async function gatherOocTinder(){
  var matches = await rpGet('rp_tinder_matches', []);
  if (!matches.length) return [];
  var me = await tdMe();
  var parts = [];
  for (var i=0;i<matches.length;i++){
    var m = matches[i];
    var msgs = (await rpGet('rp_tinder_msgs_'+m.id, [])).filter(function(x){ return !x.hidden; }).slice(-8);
    if (!msgs.length) continue;
    parts.push('Satinder: переписка '+me.name+' с '+m.name+' ('+m.age+', тип общения: '+tdArch(m.style).name+'):\n'+msgs.map(function(x){ return (x.from==='me' ? me.name : m.name)+': '+(x.kind==='photo' ? '[фото]' : x.text); }).join('\n'));
  }
  return parts;
}


var GAL_IDX = 'rp_gal_idx', GAL_CFG = 'rp_gal_cfg';
var GAL_MAX = 150;
var GAL_VIDEO_RE = /\.(mp4|webm|mov|m4v|ogv)(\?|$)/i;
var galLock = Promise.resolve();
function galQueue(fn){ var r = galLock.then(fn); galLock = r.catch(function(){}); return r; }
function galItems(){ var v = PM.store.get(GAL_IDX, 'global'); return Array.isArray(v) ? v : []; }
function galWrite(list){ PM.store.set(GAL_IDX, list, 'global'); }
function galIsVideo(it){ return !!it && (it.kind === 'video' || GAL_VIDEO_RE.test(String(it.src || ''))); }
async function galToData(url){
  url = String(url || '');
  if (/^data:/i.test(url)) return url;
  try{ return await PM.media.asDataUrl(url); }
  catch(e){
    return await new Promise(function(res){
      var im = new Image(); im.crossOrigin = 'anonymous';
      im.onload = function(){ try{ var c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight; c.getContext('2d').drawImage(im, 0, 0); res(c.toDataURL('image/jpeg', 0.9)); }catch(e2){ res(url); } };
      im.onerror = function(){ res(url); }; im.src = url;
    });
  }
}
function galShrink(src, maxSide, q){
  return new Promise(function(resolve){
    try{
      var im = new Image();
      im.onload = function(){
        try{
          var k = Math.min(1, maxSide / Math.max(im.width, im.height));
          var c = document.createElement('canvas');
          c.width = Math.max(1, Math.round(im.width*k)); c.height = Math.max(1, Math.round(im.height*k));
          c.getContext('2d').drawImage(im, 0, 0, c.width, c.height);
          resolve({ data: c.toDataURL('image/jpeg', q), w: im.width, h: im.height });
        }catch(e){ resolve(null); }
      };
      im.onerror = function(){ resolve(null); };
      im.src = src;
    }catch(e){ resolve(null); }
  });
}
async function galKeep(src, side, q){
  var data = await galToData(src);
  var sh = await galShrink(data, side, q);
  if (!sh) return null;
  var p = await PM.media.saveDataUrl(sh.data, { prefix:'img' });
  return { data: p, w: sh.w, h: sh.h };
}
async function rpGalleryAdd(url, tag){
  var data = await galToData(url);
  var full = await galShrink(data, 1280, 0.88);
  var thumb = await galShrink(data, 280, 0.7);
  if (!full || !thumb) throw new Error('картинка не открылась');
  var src = await PM.media.saveDataUrl(full.data, { prefix:'gal' });
  var th = await PM.media.saveDataUrl(thumb.data, { prefix:'galth' });
  var names = null; try{ names = await getNames(); }catch(e){}
  await galQueue(async function(){
    var idx = galItems();
    idx.unshift({ id: uid(), ts: Date.now(), tag: tag || 'Чат', fav:false, bot: names ? names.charName : '', src: src, th: th, kind:'image' });
    galWrite(idx);
  });
  galClean().catch(function(){});
}
async function galAddFromDevice(){
  var res = await rpImport({ multiple:true, extensions:['png','jpg','jpeg','webp','gif','mp4','webm','mov'], max:1600, prefix:'gal' });
  if (!res.length) return 0;
  var added = [];
  for (var i = 0; i < res.length; i++){
    var path = res[i].path, video = GAL_VIDEO_RE.test(path), th = '';
    if (!video){
      try{ var sh = await galShrink(await galToData(path), 280, 0.7); if (sh) th = await PM.media.saveDataUrl(sh.data, { prefix:'galth' }); }catch(e){}
    }
    added.push({ id: uid(), ts: Date.now() - i, tag: 'С устройства', fav:false, bot:'', src: path, th: th || (video ? '' : path), kind: video ? 'video' : 'image' });
  }
  await galQueue(async function(){ galWrite(added.concat(galItems())); });
  return added.length;
}
async function galCfg(){ return Object.assign({ days: 30 }, PM.store.get(GAL_CFG, 'global') || {}); }
async function galClean(){
  var cfg = await galCfg();
  return galQueue(async function(){
    var idx = galItems();
    if (!idx.length) return 0;
    var now = Date.now();
    var keep = [], drop = [];
    idx.forEach(function(it){
      if (it.fav) keep.push(it);
      else if (cfg.days > 0 && now - it.ts > cfg.days*86400000) drop.push(it);
      else keep.push(it);
    });
    var nonFav = keep.filter(function(x){ return !x.fav; });
    if (nonFav.length > GAL_MAX){
      var extra = nonFav.slice(GAL_MAX);
      extra.forEach(function(x){ drop.push(x); });
      keep = keep.filter(function(x){ return extra.indexOf(x) === -1; });
    }
    if (!drop.length) return 0;
    galWrite(keep);
    for (var i = 0; i < drop.length; i++){ if (drop[i].kind !== 'video' && drop[i].tag !== 'С устройства'){ await PM.media.remove(drop[i].src); if (drop[i].th && drop[i].th !== drop[i].src) await PM.media.remove(drop[i].th); } }
    return drop.length;
  });
}
var galFilter = 'all';
SCREENS.gallery = {
  title: 'Галерея',
  async render(container){
    container.style.flexDirection=''; container.style.height=''; container.style.minHeight='';
    container.style.padding = '10px 14px 16px';
    await galClean();
    await galRender(container);
  }
};
async function galRender(container){
  backTarget = openHome;
  container.innerHTML = '';
  var cfg = await galCfg();
  var idx = galItems();
  var addBtn = el('div','rp_btn rp_sm rp_gal_add','<span>+ Добавить фото или видео</span>');
  container.appendChild(addBtn);
  addBtn.addEventListener('click', async function(){
    try{ var n = await galAddFromDevice(); if (n){ toast('Добавлено: ' + n); galRender(container); } }
    catch(e){ console.error('RP gallery add failed', e); toast('Не удалось добавить: ' + (e && e.message ? e.message : e)); }
  });
  var head = el('div','rp_gal_cfg');
  head.innerHTML = '<div class="rp_muted" style="margin-bottom:5px;font-size:10.5px;">Хранить арты (избранное и добавленное вручную не удаляется):</div>'+
    '<div class="rp_td_seg" id="rp_gal_ttl" style="margin:0 0 10px;">'+
    [[1,'1 день'],[7,'7 дней'],[30,'Месяц'],[0,'Всегда']].map(function(o){ return '<div data-d="'+o[0]+'" class="'+(cfg.days===o[0]?'on':'')+'">'+o[1]+'</div>'; }).join('')+'</div>';
  container.appendChild(head);
  head.querySelectorAll('[data-d]').forEach(function(d){
    d.addEventListener('click', async function(){
      cfg.days = parseInt(d.getAttribute('data-d'),10);
      PM.store.set(GAL_CFG, cfg, 'global');
      var n = await galClean();
      if (n) toast('Удалено старых артов: '+n);
      await galRender(container);
    });
  });
  var tags = [];
  idx.forEach(function(it){ if (tags.indexOf(it.tag) === -1) tags.push(it.tag); });
  if (galFilter !== 'all' && galFilter !== 'fav' && tags.indexOf(galFilter) === -1) galFilter = 'all';
  var chips = el('div','rp_mn_chips');
  chips.innerHTML = '<div class="rp_mn_chip'+(galFilter==='all'?' on':'')+'" data-f="all">Все ('+idx.length+')</div>'+
    '<div class="rp_mn_chip'+(galFilter==='fav'?' on':'')+'" data-f="fav">★ Избранное</div>'+
    tags.map(function(t){ return '<div class="rp_mn_chip'+(galFilter===t?' on':'')+'" data-f="'+escapeHtml(t)+'">'+escapeHtml(t)+'</div>'; }).join('');
  container.appendChild(chips);
  chips.querySelectorAll('[data-f]').forEach(function(c){ c.addEventListener('click', function(){ galFilter = c.getAttribute('data-f'); galRender(container); }); });
  var shown = idx.filter(function(it){ return galFilter==='all' || (galFilter==='fav' ? it.fav : it.tag===galFilter); });
  if (!shown.length){
    container.appendChild(el('div','rp_empty', idx.length ? 'Здесь пока ничего нет.' : 'Тут будут все арты, которые сгенерирует телефон: фото в чатах, еда, посты, кадры стримов, Tinder. Включи картинки в настройках — и они начнут появляться. Фото и видео можно добавить и самой.'));
    return;
  }
  var badBar = el('div','rp_gal_bad'); badBar.style.display = 'none'; container.appendChild(badBar);
  var grid = el('div','rp_gal_grid');
  grid.innerHTML = shown.map(function(it){
    var media = galIsVideo(it) ? '<video src="'+escapeHtml(it.src)+'#t=0.1" muted playsinline preload="metadata"></video><i class="rp_gal_play">▶</i>' : '<img alt="" loading="lazy" src="'+escapeHtml(it.th || it.src)+'">';
    return '<div class="rp_gal_cell" data-id="'+escapeHtml(it.id)+'">'+(it.fav?'<i class="rp_gal_star">★</i>':'')+media+'</div>';
  }).join('');
  container.appendChild(grid);
  var bad = [];
  var paintBad = function(){ badBar.style.display = bad.length ? '' : 'none'; badBar.innerHTML = '<span>Не открываются: '+bad.length+'</span><div class="rp_btn rp_ghost rp_xs" data-rmbad="1"><span>'+(badBar.dataset.arm ? 'Точно убрать?' : 'Убрать их')+'</span></div>'; };
  badBar.addEventListener('click', async function(e){
    if (!e.target.closest('[data-rmbad]')) return;
    if (!badBar.dataset.arm){ badBar.dataset.arm = '1'; paintBad(); setTimeout(function(){ if (badBar.isConnected && badBar.dataset.arm){ badBar.dataset.arm = ''; paintBad(); } }, 3000); return; }
    var ids = bad.slice();
    await galQueue(async function(){ galWrite(galItems().filter(function(x){ return ids.indexOf(x.id) < 0; })); });
    toast('Убрано: ' + ids.length);
    galRender(container);
  });
  var cells = Array.prototype.slice.call(grid.querySelectorAll('.rp_gal_cell'));
  cells.forEach(function(cell, i){
    cell.addEventListener('click', function(){ galOpenViewer(container, shown, i); });
    var m = cell.querySelector('img,video');
    if (m) m.addEventListener('error', function(){
      var id = cell.getAttribute('data-id');
      cell.classList.add('gone'); m.remove();
      cell.insertAdjacentHTML('afterbegin', '<div class="rp_gal_dead">⚠<span>файл не найден</span></div>');
      if (bad.indexOf(id) < 0){ bad.push(id); paintBad(); }
    });
  });
}
async function galDownload(it){
  var src = it.src, ext = (String(src).split('.').pop() || 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '') || 'jpg';
  try{
    var data = await PM.media.asDataUrl(src);
    PM.media.download('art-' + it.id + '.' + ext, data.slice(data.indexOf(',') + 1), (/^data:([^;]+)/.exec(data) || [])[1]);
  }catch(e){
    console.error('RP gallery download failed', e);
    try{ PM.media.preview(src); }catch(e2){ toast('Не получилось скачать: ' + ((e2 && e2.message) || e2)); }
  }
}
async function galOpenViewer(container, list, i){
  var host = $('#rp_screen') || document.body;
  var ov = el('div','rp_gal_view');
  host.appendChild(ov);
  function draw(){
    var it = list[i];
    var media = galIsVideo(it) ? '<video src="'+escapeHtml(it.src)+'" controls playsinline autoplay></video>' : '<img src="'+escapeHtml(it.src)+'" alt="">';
    ov.innerHTML = '<div class="rp_gal_view_top"><div class="rp_gal_view_meta">'+escapeHtml(it.tag)+(it.bot?' · '+escapeHtml(it.bot):'')+' · '+escapeHtml(new Date(it.ts).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))+'</div><div class="rp_gal_x" id="rp_gal_close">✕</div></div>'+
      '<div class="rp_gal_view_img">'+media+'</div>'+
      '<div class="rp_gal_view_bar"><div class="rp_gal_b" id="rp_gal_prev">‹</div><div class="rp_gal_b'+(it.fav?' on':'')+'" id="rp_gal_fav">'+(it.fav?'★':'☆')+'</div><div class="rp_gal_b" id="rp_gal_dl">⬇</div><div class="rp_gal_b" id="rp_gal_del">'+(ov.dataset.del?'Точно?':'🗑')+'</div><div class="rp_gal_b" id="rp_gal_next">›</div></div>';
    var vm = ov.querySelector('.rp_gal_view_img img, .rp_gal_view_img video');
    if (vm) vm.addEventListener('error', function(){ var h2 = vm.parentNode; if (h2) h2.innerHTML = '<div class="rp_muted" style="text-align:center;padding:20px;">Файл не открывается</div>'; });
    $('#rp_gal_close', ov).addEventListener('click', function(){ ov.remove(); galRender(container); });
    $('#rp_gal_prev', ov).addEventListener('click', function(){ i = (i-1+list.length)%list.length; ov.dataset.del=''; draw(); });
    $('#rp_gal_next', ov).addEventListener('click', function(){ i = (i+1)%list.length; ov.dataset.del=''; draw(); });
    $('#rp_gal_dl', ov).addEventListener('click', function(){ galDownload(it); });
    $('#rp_gal_fav', ov).addEventListener('click', async function(){
      await galQueue(async function(){ var idx = galItems(); var r = idx.find(function(x){ return x.id === it.id; }); if (r){ r.fav = !r.fav; it.fav = r.fav; galWrite(idx); } });
      toast(it.fav ? 'В избранном ★' : 'Убрано из избранного');
      draw();
    });
    $('#rp_gal_del', ov).addEventListener('click', async function(){
      if (!ov.dataset.del){ ov.dataset.del = '1'; $('#rp_gal_del', ov).textContent = 'Точно?'; setTimeout(function(){ if (ov.isConnected && ov.dataset.del){ ov.dataset.del=''; var b=$('#rp_gal_del', ov); if (b) b.textContent='🗑'; } }, 3000); return; }
      await galQueue(async function(){ galWrite(galItems().filter(function(x){ return x.id !== it.id; })); });
      if (it.tag !== 'С устройства'){ await PM.media.remove(it.src); if (it.th && it.th !== it.src) await PM.media.remove(it.th); }
      list.splice(i,1); ov.dataset.del='';
      if (!list.length){ ov.remove(); galRender(container); return; }
      i = Math.min(i, list.length-1); toast('Удалено'); draw();
    });
  }
  draw();
}
async function gatherOocLove(raw){
  var parts = [];
  var notes = (await rpGet('rp_notes', [])).filter(function(n){ return !n.hidden; });
  if (notes.length) parts.push('Записки:\n'+notes.map(function(n){ return '- '+n.text; }).join('\n'));
  var reminders = (await rpGet('rp_reminders', [])).filter(function(n){ return !n.hidden; });
  if (reminders.length) parts.push('Напоминания:\n'+reminders.map(function(n){ return '- '+n.text; }).join('\n'));
  var today = await getStoryDate();
  var log = await moodLogGet('rp_mood_log');
  var pLog = await moodLogGet('rp_partner_mood_log');
  var myM = MOODS.find(function(m){ return m.id===log[today]; });
  var pM = MOODS.find(function(m){ return m.id===pLog[today]; });
  if (myM || pM){
    var names = await getNames();
    var moodTxt = 'Настроение сегодня: '+names.userName+' — '+(myM?myM.label:'—')+'; '+names.charName+' — '+(pM?pM.label:'—');
    parts.push(moodTxt);
  }
  return parts;
}
async function gatherOocFlo(raw){
  var cfg2 = await rpGet('rp_flo_config', null);
  if (!cfg2 || !cfg2.lastPeriodStart) return [];
  var today = await getStoryDate();
  var cur = floPhaseForDate(cfg2, today);
  var kd = floKeyDates(cfg2, today);
  var text = 'Цикл: день '+cur.cycleDay+' из '+cfg2.cycleLength+', фаза — '+FLO_PHASES[cur.phase].label+'. Овуляция: '+kd.ovulationDate+'. Фертильное окно: '+kd.fertileStart+' – '+kd.fertileEnd+'.';
  var marks = await rpGet('rp_flo_marks', {});
  var todaySymptoms = (marks[today] && marks[today].symptoms) || [];
  if (todaySymptoms.length){
    text += ' Самочувствие сегодня: '+todaySymptoms.map(function(sid){ var s = FLO_SYMPTOMS.find(function(x){ return x.id===sid; }); return s ? s.label : sid; }).join(', ')+'.';
  }
  return [text];
}
async function gatherOocDiary(){
  var parts = [];
  var entries = (await rpGet('rp_diary', [])).filter(function(e){ return !e.hidden; });
  if (entries.length) parts.push('Дневник:\n'+entries.slice(-6).map(function(e){ return '- '+e.text; }).join('\n'));
  var secrets = (await rpGet('rp_secrets', [])).filter(function(s){ return !s.hidden; });
  if (secrets.length) parts.push('Секреты:\n'+secrets.map(function(s){ return '- '+s.text; }).join('\n'));
  return parts;
}
async function gatherOocMemories(){
  var mems = (await rpGet('rp_memories', [])).filter(function(m){ return !m.hidden; });
  if (!mems.length) return [];
  return ['Воспоминания:\n'+mems.map(function(m){ return '- ('+m.dateLabel+') '+m.text; }).join('\n')];
}
async function gatherOocNpcs(){
  var npcs = (await rpGet('rp_npcs2', [])).filter(function(n){ return !n.hidden; });
  if (!npcs.length) return [];
  return ['НПС:\n'+npcs.map(function(n){ return '- '+n.name+(n.relation?(' ('+n.relation+')'):'')+': '+(n.about||''); }).join('\n')];
}
async function gatherOocStatus(){
  var parts = [];
  var rel = await rpGet('rp_relstatus', null);
  if (rel){
    var meta = STATUS_TYPES.find(function(s){ return s.id===rel.statusId; });
    parts.push('Статус отношений: '+(meta?meta.label:rel.statusId)+' ('+rel.score+' из диапазона -1000..1000)');
  }
  var proms = (await rpGet('rp_promises', [])).filter(function(p){ return !p.hidden; });
  if (proms.length) parts.push('Обещания:\n'+proms.map(function(p){ return '- ['+({pending:'ждём',kept:'сдержано',broken:'нарушено'})[p.status]+'] '+p.text; }).join('\n'));
  var bounds = (await rpGet('rp_boundaries', [])).filter(function(b){ return !b.hidden; });
  if (bounds.length) parts.push('Границы:\n'+bounds.map(function(b){ return '- '+b.text; }).join('\n'));
  return parts;
}
async function gatherOocTwitter(){
  var tweets = (await rpGet('rp_tweets', [])).filter(function(t){ return !t.hidden; });
  if (!tweets.length) return [];
  return ['Твиттер (последние посты):\n'+tweets.slice(0,15).map(function(t){ return t.author+': '+t.text; }).join('\n')];
}
async function gatherOocTwitch(){
  var parts = [];
  var session = await rpGet('rp_stream_session', null);
  if (session){
    var feed = await rpGet('rp_stream_feed', []);
    var chat = await rpGet('rp_stream_chat', []);
    var wmT = await rpGet('rp_hide_wm', {});
    feed = feed.slice((wmT.feed||0) <= feed.length ? (wmT.feed||0) : 0);
    chat = chat.slice((wmT.chat||0) <= chat.length ? (wmT.chat||0) : 0);
    if (feed.length) parts.push('Текущий эфир:\n'+feed.map(function(f){ return f.author+': '+f.text; }).join('\n'));
    if (chat.length) parts.push('Чат текущего стрима:\n'+chat.slice(-30).map(function(c){ return c.type==='donation' ? (c.author+' задонатил '+(c.amount||'')+': '+c.text) : (c.author+': '+c.text); }).join('\n'));
  }
  var archive = await rpGet('rp_stream_archive', []);
  var wmA = await rpGet('rp_hide_wm', {});
  archive = archive.slice((wmA.archive||0) <= archive.length ? (wmA.archive||0) : 0);
  if (archive.length) parts.push('Прошлые стримы (сводки):\n'+archive.slice(-5).map(function(a){ return '- Стрим №'+a.n+': '+a.summary; }).join('\n'));
  return parts;
}
async function sendOocParts(parts){
  if (!parts.length){ toast('Нечего отправлять — здесь пусто или всё скрыто'); return; }
  var names = await getNames();
  var prompt = 'Вот информация из этого раздела телефона персонажа '+names.charName+' и '+names.userName+' — исходные данные уже разбиты по подразделам ниже:\n\n'+parts.join('\n\n')+'\n\n'+
    'Перескажи это для внеролевой (OOC) заметки автору КОНКРЕТНО, а не общими словами. Правила:\n'+
    '- На каждый подраздел из исходных данных (например "Записки:", "Настроение сегодня:", "Переписка с Х:") — отдельное предложение или строка, начинающаяся с названия этого подраздела, например: "В записках персонаж отметил: ...", "Настроение сегодня: ...", "В переписке с Х состоялся диалог: ...".\n'+
    '- Указывай конкретные факты, реплики (по смыслу, дословно не обязательно) и детали из исходных данных — никаких обобщений вроде "они пообщались" или "было что-то важное".\n'+
    '- Без вводных фраз, сразу по пунктам, каждый пункт — новое предложение.\n'+
    'Ответь только текстом пересказа.';
  try{
    var raw = await callModel(prompt);
    var summary = String(raw||'').trim();
    if (!summary){ toast('Не удалось составить сводку'); return; }
    await PM.input.set('[OOC: '+summary+']');
    toast('Добавлено в поле ввода чата');
  }catch(e){ console.error(e); toast('Ошибка: '+(e.message||e)); }
}
function buildOocButton(key, gatherFn){
  var btn = el('div','rp_btn rp_ghost rp_xs');
  btn.innerHTML = '<svg><use href="#rpi-brackets"/></svg><span>В OOC</span>';
  wireBusyButton(btn, key, async function(){
    var parts = await gatherFn();
    await sendOocParts(parts);
    closeAppbarMenu();
  });
  return btn;
}
var HIDE_ALL = false;
function hk(){ return HIDE_ALL ? 0 : 1; }
async function hideEverythingGlobal(){
  HIDE_ALL = true;
  try{ return await hideEverythingGlobalInner(); }
  finally{ HIDE_ALL = false; }
}
async function hideTwitchOoc(){
  var wm = await rpGet('rp_hide_wm', {});
  var feed = await rpGet('rp_stream_feed', []), chat = await rpGet('rp_stream_chat', []), arch = await rpGet('rp_stream_archive', []);
  var next = { feed: feed.length, chat: chat.length, archive: arch.length };
  var changed = (wm.feed||0) !== next.feed || (wm.chat||0) !== next.chat || (wm.archive||0) !== next.archive;
  await rpSet('rp_hide_wm', next);
  return changed;
}
async function unhideTwitchOoc(){
  var wm = await rpGet('rp_hide_wm', {});
  var had = !!(wm.feed || wm.chat || wm.archive);
  await rpSet('rp_hide_wm', {});
  return had;
}
async function hideTinderAll(){
  var changed = false;
  var matches = await rpGet('rp_tinder_matches', []);
  for (var i=0;i<matches.length;i++){
    var key = 'rp_tinder_msgs_'+matches[i].id;
    var l = await rpGet(key, []);
    var c = false;
    l.forEach(function(m){ if (!m.hidden){ m.hidden = true; c = true; } });
    if (c){ await rpSet(key, l); changed = true; }
  }
  return changed;
}
