async function hwBuildCard(l, wc){
  var cols = Math.max(1, Math.min(l.cols, wc.cols || 99));
  var rows = Math.max(1, Math.min(4, wc.rows || 2));
  var card = el('div','rp_hw_card'); card.setAttribute('data-id','widget');
  card.style.gridColumn = 'span '+cols; card.style.gridRow = 'span '+rows;
  card.style.setProperty('--hwrad', (wc.radius == null ? 18 : wc.radius)+'px');
  card.setAttribute('data-cols', cols); card.setAttribute('data-rows', rows);
  var imgOn = await imagesEnabled();
  var saved = imgOn ? await rpGet('rp_home_widget_photo', null) : null;
  var boxHtml = !imgOn
    ? '<div class="ic">🖼️</div><div class="lbl">Включи картинки в настройках, чтобы получать фото</div>'
    : (saved && saved.url ? '<img src="'+escapeHtml(saved.url)+'" class="rp_hw_photo_img" alt="">'
        : '<div class="ic">🖼️</div><div class="lbl">Нажми, чтобы получить фото прямо сейчас</div>');
  if (imgOn && RP_HW_BUSY) boxHtml = rpHwBoxHtmlBusy();
  card.innerHTML = '<div class="rp_hw_photo_box" id="rp_hw_photo_box">'+boxHtml+'</div>'+
    (imgOn ? '<div class="rp_hw_btn" id="rp_hw_photo_refresh"><svg><use href="#rpi-sparkle"/></svg></div>' : '')+
    '<div class="rp_hw_resize" id="rp_hw_resize"></div>';
  if (imgOn){
    $('#rp_hw_photo_box', card).addEventListener('click', function(){ if (!HOME_EDIT) generateHomePhoto(card); });
    $('#rp_hw_photo_refresh', card).addEventListener('click', function(e){ e.stopPropagation(); if (!HOME_EDIT) generateHomePhoto(card); });
  }
  return card;
}
async function buildGrid(){
  var grid = $('#rp_grid'); if (!grid) return;
  var keep = grid.scrollTop;
  var l = await hlGet(); hlVars(l);
  var custom = await rpGet('rp_app_icon_colors', {});
  var names = await rpGet('rp_app_names', {});
  var wc = await hwConf();
  var order = await hlOrder();
  var wgs = await wgList();
  var frag = document.createDocumentFragment();
  for (var i = 0; i < order.length; i++){
    var id = order[i];
    if (id === 'widget'){ frag.appendChild(await hwBuildCard(l, wc)); continue; }
    if (/^sp_/.test(id)){ frag.appendChild(hlSpacer(id)); continue; }
    if (/^wg_/.test(id)){ var wgw = wgs.filter(function(x){ return x.id === id; })[0]; if (wgw) frag.appendChild(await wgBuild(wgw, l)); continue; }
    var app = APPS.filter(function(a){ return a.id === id; })[0];
    if (!app) continue;
    frag.appendChild(hlTile(app, custom[app.id] || app.c1, names[app.id] || app.label));
  }
  var addT = el('div','rp_tile addapp'); addT.innerHTML = '<div class="rp_tile_ico"><svg><use href="#rpi-plus"/></svg></div><div class="rp_tile_label">Добавить</div>';
  addT.addEventListener('click', function(){ hlAddAppSheet(); });
  frag.appendChild(addT);
  grid.innerHTML = ''; grid.appendChild(frag);
  grid.classList.toggle('edit', HOME_EDIT);
  clearTimeout(window.__thHomeSync); window.__thHomeSync = setTimeout(function(){ try{ Promise.all([rpGet('rp_theme', null), thEditId()]).then(function(r){ if (r[0] && r[1] && r[0].id === r[1]) return thSyncEdit(false); }).catch(function(){}); }catch(e){} }, 700);
  grid.scrollTop = keep;
}
async function renderHomeWidgets(){ await buildGrid(); }
function hlSaveOrderFromDom(){
  var ids = Array.prototype.map.call($('#rp_grid').children, function(c){ return c.getAttribute('data-id'); }).filter(Boolean);
  return rpSet('rp_home_order', ids);
}
function hlEnterEdit(){
  HOME_EDIT = true;
  var g = $('#rp_grid'); if (g) g.classList.add('edit');
  var b = $('#rp_home_editbar'); if (b) b.classList.add('on');
  var s = $('#rp_home_sessionbar'); if (s) s.style.display = 'none';
}
function hlExitEdit(){
  if (!HOME_EDIT) return;
  HOME_EDIT = false;
  var g = $('#rp_grid'); if (g) g.classList.remove('edit');
  var b = $('#rp_home_editbar'); if (b) b.classList.remove('on');
  var s = $('#rp_home_sessionbar'); if (s) s.style.display = '';
}
function hlWireHome(){
  var grid = $('#rp_grid'), home = $('#rp_home');
  var st = null;
  grid.addEventListener('pointerdown', function(e){
    var item = e.target.closest ? e.target.closest('.rp_tile, .rp_hw_card') : null;
    if (!item || !grid.contains(item)) return;
    if (e.target.closest('.rp_sp_x') || e.target.closest('.rp_wg_tools') || e.target.closest('.rp_app_x') || item.classList.contains('addapp')) return;
    if (e.target.closest('.rp_hw_resize')){
      if (!HOME_EDIT) return;
      e.preventDefault(); e.stopPropagation();
      st = { mode:'resize', item:item, x:e.clientX, y:e.clientY };
      var r = item.getBoundingClientRect(); st.w0 = r.width; st.h0 = r.height;
      st.cols0 = +item.getAttribute('data-cols') || 1; st.rows0 = +item.getAttribute('data-rows') || 1;
      return;
    }
    st = { mode:'item', item:item, x:e.clientX, y:e.clientY, moved:false, drag:false, timer:null };
    if (!HOME_EDIT){
      st.timer = setTimeout(function(){ if (st && !st.moved){ hlEnterEdit(); st.longed = true; } }, 480);
    }
  });
  grid.addEventListener('click', async function(e){
    var ax = e.target.closest ? e.target.closest('.rp_app_x') : null;
    if (ax && HOME_EDIT){
      var tl = ax.parentNode, aid = tl.getAttribute('data-id');
      var rem = await rpGet('rp_app_removed', []); if (rem.indexOf(aid) === -1) rem.push(aid);
      await rpSet('rp_app_removed', rem); tl.remove(); await hlSaveOrderFromDom();
      toast('Приложение убрано — вернуть можно кнопкой «+»'); return;
    }
    var x = e.target.closest ? e.target.closest('.rp_sp_x') : null;
    if (!x || !HOME_EDIT) return;
    var t = x.parentNode; t.remove(); await hlSaveOrderFromDom();
  });
  document.addEventListener('pointermove', function(e){
    if (!st) return;
    var dx = e.clientX - st.x, dy = e.clientY - st.y;
    if (st.mode === 'resize'){ hlResizeMove(st, dx, dy); return; }
    if (!st.drag){
      if (Math.hypot(dx, dy) > 6){
        st.moved = true;
        if (st.timer){ clearTimeout(st.timer); st.timer = null; }
        if (HOME_EDIT) hlDragStart(st, e, home, grid);
      }
      return;
    }
    hlDragMove(st, e, home, grid);
  });
  var end = async function(){
    if (!st) return;
    var s = st; st = null;
    if (s.timer) clearTimeout(s.timer);
    if (s.mode === 'resize'){
      var c = +s.item.getAttribute('data-cols'), r = +s.item.getAttribute('data-rows');
      var rid = s.item.getAttribute('data-id');
      if (/^wg_/.test(rid)) await wgUpdate(rid, { cols:c, rows:r }); else await hwSave({ cols:c, rows:r });
      return;
    }
    if (s.drag){
      if (s.ghost) s.ghost.remove();
      s.item.classList.remove('rp_dragging');
      await hlSaveOrderFromDom();
    }
  };
  document.addEventListener('pointerup', end);
  document.addEventListener('pointercancel', end);
  $('#rp_edit_done').addEventListener('click', function(){ hlExitEdit(); });
  $('#rp_edit_addapp').addEventListener('click', function(){ hlAddAppSheet(); });
  $('#rp_edit_space').addEventListener('click', async function(){
    var id = 'sp_' + uid();
    grid.appendChild(hlSpacer(id)); await hlSaveOrderFromDom();
    grid.scrollTop = grid.scrollHeight;
  });
  $('#rp_edit_reset').addEventListener('click', async function(){
    await rpSet('rp_home_order', []); await buildGrid(); toast('Порядок сброшен');
  });
}
function rpZoom(){ var f = document.getElementById('rp_frame'); var z = f ? parseFloat(getComputedStyle(f).zoom) : 1; return z > 0 ? z : 1; }
function hlDragStart(st, e, home, grid){
  st.drag = true;
  var r = st.item.getBoundingClientRect();
  var hr = home.getBoundingClientRect();
  st.offX = st.x - r.left; st.offY = st.y - r.top;
  var g = st.item.cloneNode(true);
  g.classList.add('rp_drag_ghost'); g.removeAttribute('id');
  var zz = rpZoom();
  g.style.width = (r.width / zz)+'px'; g.style.height = (r.height / zz)+'px';
  g.style.left = ((r.left - hr.left) / zz)+'px'; g.style.top = ((r.top - hr.top) / zz)+'px';
  g.style.gridColumn = 'auto'; g.style.gridRow = 'auto';
  home.appendChild(g); st.ghost = g;
  st.item.classList.add('rp_dragging');
}
function hlDragMove(st, e, home, grid){
  var hr = home.getBoundingClientRect();
  var zz = rpZoom();
  st.ghost.style.left = ((e.clientX - st.offX - hr.left) / zz)+'px';
  st.ghost.style.top = ((e.clientY - st.offY - hr.top) / zz)+'px';
  var gr = grid.getBoundingClientRect();
  if (e.clientY < gr.top + 28) grid.scrollTop -= 7;
  else if (e.clientY > gr.bottom - 28) grid.scrollTop += 7;
  var kids = Array.prototype.slice.call(grid.children);
  var target = null;
  for (var i = 0; i < kids.length; i++){
    if (kids[i] === st.item) continue;
    var rr = kids[i].getBoundingClientRect();
    if (e.clientX >= rr.left && e.clientX <= rr.right && e.clientY >= rr.top && e.clientY <= rr.bottom){ target = kids[i]; break; }
  }
  if (target){
    var from = kids.indexOf(st.item), to = kids.indexOf(target);
    if (from < to) target.after(st.item); else target.before(st.item);
  } else if (kids.length){
    var last = kids[kids.length - 1] === st.item ? kids[kids.length - 2] : kids[kids.length - 1];
    if (last){ var lr = last.getBoundingClientRect(); if (e.clientY > lr.bottom) grid.appendChild(st.item); }
  }
}
function hlResizeMove(st, dx, dy){
  var grid = $('#rp_grid');
  var zz = rpZoom(); dx = dx / zz; dy = dy / zz;
  var l = { cols: +getComputedStyle($('#rp_root')).getPropertyValue('--hcols') || 5 };
  var gs = getComputedStyle(grid);
  var inner = grid.clientWidth - parseFloat(gs.paddingLeft) - parseFloat(gs.paddingRight);
  var gapX = parseFloat(gs.columnGap) || 4, gapY = parseFloat(gs.rowGap) || 8;
  var cellW = (inner - (l.cols - 1) * gapX) / l.cols;
  var rowH = parseFloat(gs.gridAutoRows) || 76;
  var nc = Math.round((st.w0 / zz + dx + gapX) / (cellW + gapX));
  var nr = Math.round((st.h0 / zz + dy + gapY) / (rowH + gapY));
  nc = Math.max(1, Math.min(l.cols, nc)); nr = Math.max(1, Math.min(4, nr));
  st.item.style.gridColumn = 'span '+nc; st.item.style.gridRow = 'span '+nr;
  st.item.setAttribute('data-cols', nc); st.item.setAttribute('data-rows', nr);
}

