  var box = el('div','cas_bet'+(locked ? ' off' : '')); box.id = 'cas_betbox';
  box.innerHTML = '<div class="cas_bet_row"><button data-a="half">½</button><input id="cas_bet_in" type="number" min="0" value="'+CAS.bet+'"><button data-a="dbl">×2</button><button data-a="max">MAX</button></div>'+
    '<div class="cas_chips">'+chips.map(function(c){ return '<div class="cas_chip" data-v="'+c+'">'+fmtMoney(c)+'</div>'; }).join('')+'</div>';
  host.appendChild(box);
  var inp = $('#cas_bet_in', box);
  var setV = async function(v){ var b = await getBankBalance(); v = casRoundMoney(Math.max(0, Math.min(v, b))); CAS.bet = v; inp.value = v; if (CAS.onBet) CAS.onBet(); };
  box.querySelectorAll('[data-a]').forEach(function(b){ b.addEventListener('click', function(){ var a = b.getAttribute('data-a'); setV(a==='half' ? casBetValue()/2 : (a==='dbl' ? casBetValue()*2 : 1e15)); }); });
