  CAS.onBet = null;
  backTarget = CAS.view === 'lobby' ? openHome : async function(){ await casLeaveGame(); CAS.view = 'lobby'; casRender(container); };
  container.innerHTML = '';
  var app = el('div','cas_app'); container.appendChild(app); CAS.root = app;
  app.innerHTML = '<div class="cas_top"><div class="cas_logo">CASINO ROYALE</div><div class="cas_bal"><span>Твой счёт</span><b id="cas_bal_v">…</b></div></div><div class="cas_main" id="cas_main"></div>';
  var main = $('#cas_main', app);
