async function stkStreakInfo(){
  var ch = await stkChat(), today = await getStoryDate(), s = ch.streak;
  var diff = s.last ? daysBetweenISO(s.last, today) : 99;
  return { n: diff <= 1 ? s.n : 0, state: !s.last ? 'none' : (diff === 0 ? 'active' : (diff === 1 ? 'dying' : 'cold')), best: s.best };
}
async function stkStreakTouch(ch){
  var today = await getStoryDate(), s = ch.streak;
  if (s.last === today) return false;
  var diff = s.last ? daysBetweenISO(s.last, today) : 99;
  s.n = diff === 1 ? s.n + 1 : 1; s.last = today; s.best = Math.max(s.best || 0, s.n);
  return s.n;
}
