async function stkGenFeed(n){
  var names = await getNames(), card = await getCharCard();
  var prompt = 'Придумай '+(n||6)+' вымышленных коротких видео из соцсети Сатток (русскоязычный аналог тиктока) от разных вымышленных авторов — уличные, бытовые, смешные, красивые, как в реальной ленте. Мир истории (для фона): '+(card.facts||'обычный современный город')+'.\n'+
    'Формат СТРОГО одна строка на видео, поля через « | »:\nник (латиницей, начинается с @) | имя автора | подпись с 1–3 хештегами (до 110 символов) | название звука | один эмодзи | сцена кадра на английском (одно предложение, что видно в вертикальном кадре) | число лайков (от 300 до 900000)\nБез нумерации и пояснений.';
  var raw = await callModel(prompt), out = [];
  String(raw||'').split('\n').forEach(function(line){
    var p = line.split('|').map(function(x){ return x.trim(); });
    if (p.length < 6 || !/^@/.test(p[0])) return;
    out.push({ id:'p_'+uid(), by:'npc', user:p[0].slice(0,24), name:p[1].slice(0,30), caption:p[2].slice(0,140), music:p[3].slice(0,40)||'Оригинальный звук', emoji:(p[4]||'✨').slice(0,4), scene:p[5].slice(0,260),
      likes:Math.abs(parseInt(String(p[6]||'').replace(/\D/g,''),10))||Math.floor(500+Math.random()*60000), comments:0, saves:0, shares:0, ts:Date.now() });
  });
  out.forEach(function(p){ p.comments = Math.max(3, Math.floor(p.likes*(0.01+Math.random()*0.03))); p.saves = Math.floor(p.likes*(0.02+Math.random()*0.05)); p.shares = Math.floor(p.likes*Math.random()*0.03); });
  return out;
}
