function thSnapshotVars(){
  var cs = getComputedStyle($('#rp_root')), v = {};
  TH_VARS.forEach(function(k){ v[k] = cs.getPropertyValue('--'+k).trim(); });
  return v;
}
async function thWallApply(){
  var home = $('#rp_home'), root = $('#rp_root'); if (!home) return;
  var w = null; try{ w = await rpGet('rp_wall', null); }catch(e){}
  var src = '';
  if (w && w.id){
    if (w.id.indexOf('url:') === 0) src = w.id.slice(4);
    else { var lib = await thLib(); var it = lib.filter(function(x){ return x.id === w.id; })[0]; if (it) src = it.data; }
  }
  var oldVid = $('#rp_wall_video'), oldDim = $('#rp_wall_dim');
  if (oldVid) oldVid.remove();
  if (oldDim) oldDim.remove();
  if (!src){ home.style.background = ''; root.classList.remove('rp_has_wall'); return; }
  var dim = Math.max(0, Math.min(85, w.dim == null ? 30 : w.dim)) / 100;
  var safe = String(src).replace(/["'()\\\s]/g, function(c){ return encodeURIComponent(c); });
  if (/\.(mp4|webm|mov|m4v|ogv)(\?|$)/i.test(src)){
    home.style.background = '';
    var v = document.createElement('video');
    v.id = 'rp_wall_video'; v.src = src; v.muted = true; v.loop = true; v.autoplay = true; v.playsInline = true;
    var shade = document.createElement('div'); shade.id = 'rp_wall_dim'; shade.style.background = 'rgba(0,0,0,' + dim + ')';
    home.insertBefore(shade, home.firstChild); home.insertBefore(v, home.firstChild);
    try{ v.play(); }catch(e){}
  } else {
    home.style.background = 'linear-gradient(rgba(0,0,0,'+dim+'),rgba(0,0,0,'+dim+')), url("'+safe+'") center/cover no-repeat';
  }
  root.classList.add('rp_has_wall');
}
async function thSetWall(w){ await rpSet('rp_wall', w); await thWallApply(); }
async function thInit(){
  try{
    var t = await rpGet('rp_theme', null);
    if (t && t.vars){
      var root = $('#rp_root');
      TH_VARS.forEach(function(k){ if (t.vars[k]) root.style.setProperty('--'+k, t.vars[k]); });
      root.classList.toggle('rp_icons_accent', t.iconMode === 'accent'); root.classList.toggle('rp_flat', !!t.flat);
    }
  }catch(e){ console.error('RP theme init failed', e); }
  await thWallApply();
}
async function thApply(t){
  var root = $('#rp_root');
  TH_VARS.forEach(function(k){ if (t.vars && t.vars[k]) root.style.setProperty('--'+k, t.vars[k]); });
  root.classList.toggle('rp_icons_accent', t.iconMode === 'accent'); root.classList.toggle('rp_flat', !!t.flat);
  var patch = {};
  if (t.shape != null) patch.shape = t.shape;
  if (t.size) patch.size = t.size;
  if (Object.keys(patch).length) await hlSave(patch);
  if (t.custom && t.home){
    try{
      if (t.home.layout) await rpSet('rp_home_layout', t.home.layout);
      await rpSet('rp_home_order', t.home.order || []);
      await wgSaveList(t.home.wgts || []);
      await rpSet('rp_app_removed', t.home.removed || []);
    }catch(e){ console.error('RP theme home restore failed', e); }
  }
  if (t.custom){
    if (t.colors) await rpSet('rp_app_icon_colors', t.colors);
    if (t.names) await rpSet('rp_app_names', t.names);
    await rpSet('rp_theme_edit', t.id);
    await thSetWall(t.wall || null);
  }
  await rpSet('rp_theme', { id:t.id, name:t.name, vars:t.vars, iconMode:t.iconMode, flat:!!t.flat });
  await buildGrid();
}

