  RP_CHAT_ID = id;
  SAT_ME_AV = null; RP_LOOK_LEGACY = null; RP_LOC_LOADED = false; RP_DATE_REF = null; RP_TICK_COUNT = -1;
  CX.open = null; CX.hubOk = false; CX.busy = {}; CX.again = {}; CX.lastCount = null; CX.lastSync = 0; CX_LB.found = null; CX_LB.err = '';
